// =====================================================================
//  Avisos e novidades: tudo o que é novo e importante aparece num painel
//  depois do login (uma vez por novidade) e fica no ❓ Ajuda.
//  O primeiro aviso é sempre o do uso de internet: o jogo é todo on-line
//  e, no 4G/5G, gasta dados do plano (crédito).
// =====================================================================
'use strict';
const Avisos = (() => {
  // novidades importantes, a mais nova no topo. Para avisar algo novo: põe aqui com um id novo.
  const NOVIDADES = [
    { id: 'n187', data: '27/11', t: '✨ Habilidades com cara própria', d: 'Os <b>32 buffs</b> e as <b>10 curas</b> eram todos a mesma runa no chão com uma coluna de luz. Agora cada tipo tem a sua forma: <b>escudos</b> com placas hexagonais, <b>Pele de Pedra</b> com rochas grudando no corpo, <b>asas</b> de penas, <b>Olho de Falcão</b> com um olho dourado na cabeça, <b>fúria</b> com chamas e ondas de choque, <b>veneno</b> pingando, <b>bênção</b> com auréola e penas caindo, <b>vazio</b> com orbes roxos, <b>tesouro</b> com moedas, <b>Sobrecarga</b> com raios, <b>canção</b> com notas, <b>espíritos</b> girando, <b>tempo</b> com um relógio no chão e <b>promessas</b> com corações. Nas curas: cruz verde, sol dourado, espiral d’água, corações, aurora colorida, folhas brotando, penas de fênix e a marca da Escolha.' },
    { id: 'n186', data: '27/11', t: '👻 Bichos com formas novas', d: 'Onze bichos eram o mesmo fantasma de capuz trocando só a cor. Agora cada um tem o seu jeito: <b>Eco Faminto</b> é uma boca cheia de dentes que flutua; <b>Sombra Errante</b>, uma serpente de sombra; <b>Eco das Cinzas</b>, uma brasa com cinzas girando; <b>Memória Aprisionada</b>, um cristal com um vulto preso dentro; <b>Eco da Cidade</b>, um lampião vivo de chama azul; <b>Memória Afogada</b>, de cabelo comprido flutuando; <b>Lume Errante</b>, uma chama com faíscas; <b>Sussurro da Névoa</b>, uma nuvem cheia de olhinhos; <b>Dama sem Olhos</b>, de vestido e véu; <b>Sombra do Vale</b>, um vulto magro de braços até o chão. E ainda: <b>Serpente das Ondas</b> com barbatanas e <b>Guarda de Ossos</b> virou esqueleto de lança.' },
    { id: 'n185', data: '27/11', t: '🏰 Castelo da guilda gigante', d: 'O <b>castelo da guilda</b> ficou <b>2,4 vezes maior</b> em tudo: saguão, arsenal, banquete, biblioteca e vestíbulo, com o teto lá no alto. Agora dá para correr à vontade nas brincadeiras das 21h. Os NPCs, os baús escondidos, os bonecos e os monstros da Caçada se espalharam pelo castelo novo.' },
    { id: 'n184', data: '27/11', t: '💬 NPCs conversando e fofocas', d: 'Os NPCs e os moradores agora <b>conversam entre si</b> quando estão perto: o preço do pão, o vizinho que ronca, a forja do Doran... E o povo <b>fofoca sobre os personagens da história</b>: os irmãos do Kravenox, os portais da Seraphyne, os cristais de memória da Lyra, a Queda de Valdora. Quando uma fofoca acontece pertinho de você, ela aparece também no chat (👂) para dar tempo de ler.' },
    { id: 'n183', data: '27/11', t: '🎵 Cada lugar com a sua música', d: 'Acabaram as músicas repetidas: agora cada cidade e cada região tem a sua. Entraram 8 trilhas do RPG Kravenox que ainda não tocavam no jogo: <b>Fortaleza das Bandeiras</b>, <b>castelo da guilda</b>, <b>Templo da Primeira Raiz</b>, <b>Templo do Eco Selado</b>, <b>Margem das Memórias</b>, <b>Rio das Memórias</b>, <b>Galerias Afogadas</b> e <b>Porta dos Três Espinhos</b>.' },
    { id: 'n182', data: '27/11', t: '🏰 Solmira virou a capital', d: 'Solmira cresceu de verdade e virou a <b>capital do Reino</b>: <b>muralha de pedra</b> com 12 torres cercando a cidade inteira, portões leste e oeste com guardas, a <b>Avenida Real</b> com lampiões e árvores subindo até o <b>Castelo de Solmira</b> ao norte (torre central, 4 torres e estandartes), outra avenida até a <b>Catedral</b> ao sul (vitral colorido e duas torres), <b>bairros</b> com 24 casas novas, <b>praça do mercado</b> com barracas e um <b>parque com lago</b>. Agora são <b>30 moradores</b> andando por tudo. Os NPCs da praça continuam no mesmo lugar.' },
    { id: 'n181', data: '27/11', t: '⏱️ Recarga das habilidades, MVPs e Ir até lá', d: '<b>Recarga:</b> agora aparece o tempo de recarga de cada habilidade (na janela de habilidades e em segundos em cima do ícone na barra), e a <b>DEX diminui a recarga</b> como no Ragnarok: 0,3% por ponto (a INT ajuda 0,1%), até 40% a menos. <b>👑 Painel de MVP:</b> ganhou os <b>Chefes de campo</b> (os MVPs de verdade: quem está vivo agora, quando vai embora e daqui a quanto tempo cada um aparece) e os <b>⭐ Alfas</b> (onde aparecem e se tem um perto de você). <b>Ir até lá:</b> para um lugar em outro mapa (como o Rei Caranguejo, na Praia), o personagem agora vai passagem por passagem; antes ficava indo e voltando numa passagem. Valeu, Wesley!' },
    { id: 'n180', data: '27/11', t: '🥖 Solmira acordou: lojinhas e conversa', d: 'Solmira ganhou <b>6 lojinhas</b> na frente das casas novas: <b>Padaria</b>, <b>Livraria</b>, <b>Peixaria</b>, <b>Floricultura</b>, <b>Alfaiate</b> e <b>Quitanda</b>, cada uma com toldo listrado, placa, mercadoria no balcão e o seu vendedor (são de enfeite: a gente não compra nelas). Os vendedores anunciam ("Pão quentinho, saindo do forno!"), os moradores passam nos balcões para comprar e se cumprimentam quando se cruzam na rua.' },
    { id: 'n179', data: '27/11', t: '🗺️ Mapa ampliado novo e clique longe no PC', d: '<b>Mapa:</b> ao abrir uma região (tocando nela no Mapa do Mundo ou no minimapa), o mapa agora é desenhado como o Mapa do Mundo: campos, matas com árvores, rios, deserto, casinhas nas cidades e nomes em letra de mapa antigo. Saíram os pontinhos de todos os bichos; ficam só os chefes (☠) e os chefes de campo (★). Toque num ponto e o personagem vai até lá. <b>PC:</b> apontar o mouse para longe não vira mais o sinal de <b>+</b> (o jogo achava que tinha um bicho ali), e clicar bem longe faz o personagem ir naquela direção (até 70 m), seguindo o relevo.' },
    { id: 'n178', data: '27/11', t: '🚶 Solmira cheia de gente', d: 'Agora <b>16 moradores</b> andam pela cidade de Solmira: aldeões, senhoras, mascates, crianças correndo, a anciã e outros. Eles passeiam pela volta da praça, pela rua de pedra e param na porta das casas. Quando estão parados perto de você, olham para você.' },
    { id: 'n177', data: '27/11', t: '💎 Cristais da Mina em pixel art', d: 'Os veios de minério da <b>Mina da Forja</b> agora são desenhados em pixel art, como os personagens: lascas de cristal com contorno, sombra e brilho, em <b>cobre</b> (Minério Rúnico) e <b>azul-aço</b> (Pedra de Têmpera), sem aquele brilho de neon. O minério do carrinho e do monte ganhou as mesmas cores.' },
    { id: 'n176', data: '27/11', t: '🎵 Quatro músicas novas', d: '<b>Torre do Cisma:</b> música nova, épica e sombria, com cordas, trompas, coro e tímpanos (a antiga, lenta e pesada, saiu). <b>Mina da Forja:</b> canção de trabalho com batidas de bigorna. <b>Cripta das Cartas:</b> misteriosa, com celesta e harpa. <b>Arena de Solmira:</b> música de batalha com tambores taiko e metais. Antes a Mina e a Cripta repetiam a música das masmorras, e a Arena a da fortaleza.' },
    { id: 'n175', data: '27/11', t: '🏘️ Solmira virou mini cidade', d: 'A <b>Vila de Solmira</b> cresceu: <b>7 casas novas</b> num segundo anel, uma <b>torre do sino</b> com relógio ao norte, <b>portões de pedra</b> com torrinhas, estandartes e a placa <b>SOLMIRA</b> nas entradas leste e oeste, <b>rua de pedra</b> da praça até os portões com <b>postes de lampião</b> e bancos, <b>barracas de feira</b> dos dois lados da rua e canteiros de flores. Os NPCs continuam todos no mesmo lugar.' },
    { id: 'n174', data: '27/11', t: '⛏️ Mina da Forja com cara de mina', d: 'A <b>Mina da Forja</b> deixou de ser um salão de piso e parede lisa. Agora é uma mina de verdade: chão de terra, paredes de rocha bruta, estalactites no teto, pedras soltas, escoras de madeira com lampiões balançando, veios de 🔶 Minério Rúnico e 🔷 Pedra de Têmpera brilhando na rocha, carrinho cheio de minério nos trilhos, barris, caixotes, picareta e poeira no ar.' },
    { id: 'n173', data: '26/11', t: '🚶 Outros jogadores e bichos andando liso', d: 'Os outros jogadores e os bichos andavam aos trancos (corriam e freavam várias vezes por segundo). Agora andam em velocidade constante, lisinho. Os bichos também pararam de andar tortos, balançando de um lado para o outro.' },
    { id: 'n172', data: '26/11', t: '🎨 Personagens mais nítidos', d: 'Os desenhos dos personagens, NPCs e bichos deixaram de ficar borrados: agora são ampliados com cuidado e ficam nítidos mesmo de perto. O andar também ficou mais reto, sem o personagem balançando torto.' },
    { id: 'n171', data: '26/11', t: '🃏 Mais cartas de anel e Vale mais natural', d: '<b>Cartas de anel:</b> antes só existia 1 carta de anel para montar com a Cartomante Zaíra; agora são <b>6</b> (cartas de crítico, SP e velocidade de vários bichos).<br><b>Vale dos Mortos:</b> os túmulos de terra deixaram de ser todos iguais e lisos: cada monte tem forma, tamanho e tom de terra diferentes, com pedrinhas soltas em volta.' },
    { id: 'n170', data: '26/11', t: '👑 Painel de MVP e 🪽 Ressuscitar', d: '<b>👑 MVP e chefes</b> (botão lá em cima, ideia do Ludi): todos os chefes do mapa com nível, lugar, se está <b>vivo</b>, <b>quanto falta para renascer</b>, <b>quem matou por último</b> e o que pode soltar. "Ir até lá" leva você.<br><b>🪽 Ressuscitar:</b> Lyra, Seraphyne, Erya e Mãe ganharam a habilidade (4 níveis: volta com 25%, 50%, 75% ou 100% da vida). Quem não é dessas classes usa a <b>🪶 Pena da Fênix</b> (loja de poções). Quem cai perto de amigos espera até 20 s por ajuda, com botão para voltar logo para a cidade.<br><b>✨ Magias:</b> o nome da habilidade aparece em cima da cabeça de quem soltou (você e os chefes).' },
    { id: 'n169', data: '26/11', t: '🔍 Tamanho da tela e portais', d: '<b>Tamanho da tela:</b> no ☰ Mais tem o <b>🔍 Tamanho da tela</b>. No <b>Automático</b> o jogo ajusta pelo aparelho (no computador fica tudo maior; em celular pequeno, menor). Dá para escolher Pequeno, Normal, Grande ou Bem grande.<br><b>Portais:</b> agora são cheios de névoa brilhante girando por dentro, dos dois lados.<br><b>Valdora:</b> a cinza que cai era quadrada; agora são flocos redondos (o mesmo nas estrelas da Cidade Submersa e nos vaga-lumes da Floresta).' },
    { id: 'n168', data: '26/11', t: '🚶 Andar melhor (lote 2)', d: '<b>Andar:</b> o personagem não fica mais trocando de lado perto da virada, dá o passo mais rápido e sobe e desce a cada passo (antes parecia deslizar). Virando sozinho no AUTO, vira mais rápido.<br><b>Bichos:</b> pararam de "pular" andando: agora dão passinhos com balanço.<br><b>Mapa:</b> o zoom não trava mais (o fundo era refeito a cada quadro).<br><b>Habilidades:</b> não aprendida fica cinza com cadeado grande; sem SP fica azulada escrito SP.<br><b>NPC:</b> sumiu o quadrado em volta do medalhão (relógio) em cima da cabeça.<br><b>Mercador Orlo</b> procura um lugar livre na praça.<br><b>Seguir/AUTO</b> dá a volta em obstáculos maiores (lago do Oásis).' },
    { id: 'n167', data: '26/11', t: '🔧 Lote de correções (1)', d: '<b>Segundo plano:</b> fora da janela o jogo continua, e na volta não explode mais tudo de uma vez (números, efeitos e sons não ficam acumulando).<br><b>Troca:</b> quem termina primeiro mantém a troca visível por mais tempo (o outro às vezes não recebia) e a lista não volta para o topo quando o outro mexe.<br><b>Casa:</b> portas de verdade para os cômodos (moldura, portal e placa com o nome); o Mestre de Obras saiu de trás das tábuas.<br><b>Refino e estrelas</b> são da peça: quando ela sai da sua mão, não passam para a próxima igual.<br><b>Alvo:</b> agora vale tocar no corpo todo do bicho (MVP grande ficou fácil).<br><b>❤️ Vida baixa:</b> a tela pisca vermelho e o coração bate abaixo de 30%.<br><b>AUTO:</b> nova opção "usar habilidade de cura abaixo de X%".<br><b>Cartas:</b> a lista rola. <b>Poções:</b> todas com escolha de quantidade. <b>🚪 Sair</b> na Torre, Abismo e masmorras. <b>Guilda:</b> brincadeiras às <b>21h</b>. <b>Som</b> de luta longe (grupo) não toca mais. <b>Ficha aberta:</b> os botões de luta continuam funcionando.' },
    { id: 'n166', data: '25/11', t: '🪤 Mascote igual ao Rag: até 5 iscas', d: 'Cada captura usa <b>até 5 iscas</b> do bicho. <b>Quanto mais iscas você juntar (até 5), maior a chance</b>: com 5 a chance é cheia, com 3 é 3/5 dela, e assim por diante. E quanto <b>menos vida</b> o bicho tiver, maior também. Antes de jogar, o jogo mostra quantas iscas vai usar e a chance. Se falhar, as iscas usadas se perdem.<br>As iscas agora <b>caem mais</b> (bicho comum 2,5%, chefe 15%), para dar para juntar 5.' },
    { id: 'n165', data: '25/11', t: '🎯 Alvo e jogo em segundo plano', d: '<b>Alvo (como no Rag):</b> <b>toque no bicho</b> (no PC, clique) e ele vira o seu alvo: aparece um <b>círculo vermelho</b> embaixo dele e a barra com nome e vida lá em cima. O <b>ataque e as habilidades vão nele</b> (não mais no mais perto: bom para os MVPs). Toque nele de novo, ou na barra, para ir bater. ✕ larga o alvo.<br><b>Mascote:</b> a isca vai no alvo escolhido. Se a chance estiver baixa, o jogo avisa antes de gastar a isca: bata no bicho até ele ficar fraco.<br><b>Segundo plano:</b> no computador, pode ir para outra janela que o jogo <b>continua</b> (caça automática, missões). Só a tela não é desenhada enquanto você não olha.' },
    { id: 'n164', data: '25/11', t: '🪑 Móveis: o que falta + PC no lugar', d: '<b>Móveis:</b> na bancada de reformas e com a Governanta Clara, cada móvel mostra <b>o que falta</b> (ex.: "falta: 3 Raiz Seca, 2 Lã"). Tocando nele aparece quanto você tem de cada coisa e <b>de onde vem</b> (qual bicho solta ou se vem do Sítio). A mochila e o baú contam juntos.<br><b>Computador:</b> agora sim os ícones ficam no meio, as missões à direita e as mensagens à esquerda, igual ao celular.' },
    { id: 'n163', data: '25/11', t: '💻 No computador igual ao celular', d: '<b>Computador:</b> agora a tela é igual à do celular (ícones no meio, missões à direita) e tem os botões de <b>ataque, pulo, esquiva e AUTO</b> para clicar com o mouse. O teclado continua valendo.<br><b>Mapa:</b> o zoom de cada lugar ficou no estilo do Mapa do Mundo (pergaminho).<br><b>Casa:</b> móvel comprado vai para um <b>lugar surpresa</b> da sala; para mudar, peça à <b>Governanta Clara</b> ("Mudar os móveis de lugar"). Ela não fica mais presa dentro dos móveis.<br><b>Refino:</b> dá para <b>desligar a animação</b> do Doran na ferraria (fica mais rápido).' },
    { id: 'n162', data: '25/11', t: '🤖 AUTO: acabou o "parado do lado do bicho"', d: 'Achamos o motivo do personagem parecer travado: na caça ele parava <b>20 cm fora do alcance</b> do golpe e ficava batendo no vento para sempre (quem luta de perto sofria mais). Agora ele chega um pouco mais perto e acerta.<br>Também: não escolhe mais bicho <b>do outro lado do rio</b> nem bicho <b>dentro de cidade</b> (onde não dá para bater), e os bichos que estavam dentro da Vila saem andando para fora.' },
    { id: 'n161', data: '25/11', t: '🤖 Caça automática com alcance grande', d: 'Com o <b>alcance da caçada no máximo</b>, o AUTO escolhia um bicho a mais de 45 m, o jogo largava esse bicho por estar longe, ele escolhia o mesmo de novo... e o personagem ficava <b>parado</b> (parecia que empurrava a pedra). Corrigido: agora ele vai até o bicho, contornando pedra e árvore. A lista de bichos da caça também mostra todos até o alcance escolhido.' },
    { id: 'n160', data: '25/11', t: '🗿 Templo da Primeira Raiz arrumado', d: '<b>Baú no meio do túnel:</b> um baú escondido tinha nascido bem no meio do túnel e fechava a passagem. Agora os baús só aparecem em lugar aberto (e nunca dentro de cidade).<br><b>Entrada:</b> o chão subia com a encosta bem na frente da parede e o personagem parecia atravessar a pedra. Agora a chegada é plana até o túnel.<br><b>AUTO:</b> para sair do Templo (ir até a Lira) ou entrar (ir até a estátua), ele passa pela boca do túnel em vez de dar cabeçada na parede da sala.' },
    { id: 'n159', data: '25/11', t: '♻️ Botão Resetar no lugar', d: 'Na <b>ficha do personagem</b>, o botão <b>Resetar</b> caía em cima dos atributos. Agora ele fica ao lado dos "Pontos para distribuir", e cada atributo tem uma linha inteira, com a explicação sem ficar espremida.' },
    { id: 'n158', data: '25/11', t: '🃏 Cartas desenhadas', d: 'Na mochila, cada <b>carta aparece como uma cartinha de verdade</b>, com o <b>desenho do monstro</b> dentro e a moldura pela raridade: <b>prata</b> (comum), <b>bronze</b> (chefe menor e alfa), <b>ouro</b> (chefe), <b>roxa</b> (arcana) e <b>vermelha</b> (Campeão Sombrio). A carta grande também ganhou a cor dela.<br><b>Mochila:</b> o ATQ, DEF e HP agora ficam embaixo do nome (antes ficavam cortados no fim da tela no celular pequeno).' },
    { id: 'n157', data: '25/11', t: '◀ Seta do quadro de mensagens no lugar', d: 'Se o quadro de mensagens estava aberto <b>grande</b> e você escondia ele, a setinha ficava <b>lá em cima, por cima do seu retrato</b>. Agora ela fica sempre no lugar do quadro normal.' },
    { id: 'n156', data: '25/11', t: '🏕️ Bichos fora das cidades', d: 'As <b>Raízes Negras</b> estavam nascendo <b>dentro do Acampamento de Valdora</b>, do lado do quadro. Agora nenhum bicho comum nasce nem passeia dentro de cidade (os da invasão continuam invadindo).<br>Na <b>Praia de Cômodo</b> os bichos voltaram a perseguir: a regra de "não entra na cidade" estava valendo para a praia inteira, e agora vale só para a vila.' },
    { id: 'n155', data: '25/11', t: '📜 Ficha do personagem nova', d: 'Toque no <b>seu nome</b> (o quadro com HP, SP e XP): abre a <b>ficha em tela cheia</b>, com botão <b>⬅ Voltar</b>.<br>• <b>XP em %</b> bem grande (ex.: 86,52%) e quanto falta para o próximo nível.<br>• HP, SP, créditos e tempo jogado.<br>• Atributos com o + e uma barrinha de quanto cada um pesa no seu personagem.<br>• <b>Combate:</b> ataque, ataque mágico, defesa, vida, SP, ataques por segundo, dano por segundo, crítico, esquiva, velocidade, alcance, roubo de vida, bônus de cartas e guilda.<br>• <b>Jornada:</b> monstros, chefes, bestiário, cartas, andar da Torre e desmaios.<br>• O <b>estilo</b> do seu personagem e um <b>código</b> que muda a cada ponto e equipamento: nenhum personagem é igual ao outro.' },
    { id: 'n154', data: '25/11', t: '🤖 AUTO contorna obstáculos e bichos voltam', d: '<b>Caça automática:</b> antes ia em linha reta até o bicho e ficava empurrando árvore, carroça ou cerca. Agora <b>contorna</b> o obstáculo. Se o bicho estiver num lugar sem caminho (outro lado do rio), larga ele e escolhe outro.<br><b>Andar sozinho até a missão:</b> calcula o caminho em volta do que estiver na frente e insiste bem mais antes de desistir.<br><b>No quadro:</b> chegou na frente, para (acabou o vai e vem).<br><b>Bichos sumindo</b> (ex.: Sentinelas da Muralha de Valdora): quando a internet caía e voltava sem ninguém on-line, sobravam só 150 bichos no mundo. Corrigido: todos voltam.<br><b>Torre:</b> cada onda nova nasce com a vida cheia.' },
    { id: 'n153', data: '25/11', t: '🗼 Torre corrigida', d: '<b>Bichos sem vida que voltavam:</b> na Torre, quando alguém do grupo matava um bicho (ou você voltava de andar), ele podia reaparecer <b>quase sem vida</b> e dava para matar de novo sem parar. Corrigido: bicho morto na Torre fica morto.<br><b>Sair da Torre:</b> o botão 🚪 agora só aparece <b>perto da placa ⬇ SAÍDA</b> e pergunta antes de sair (antes aparecia no andar todo e quem tocava no 💬 saía sem querer).' },
    { id: 'n152', data: '25/11', t: '🌊 Não trava mais na beira do rio', d: 'Às vezes o personagem ficava <b>preso na margem do rio</b> (e em outros cantos), e o AUTO parava com "Caminho bloqueado". Agora, se ele ficar preso, o jogo empurra para o chão firme mais perto e ele segue até a ponte sozinho. Pode deixar no AUTO fazendo as missões tranquilo.' },
    { id: 'n151', data: '25/11', t: '📜 Para na frente do quadro e AUTO mais esperto', d: '<b>Quadro de Caça:</b> tocou na missão para voltar ao quadro, o personagem para <b>bem na frente dele</b>, virado para ele, e o botão <b>Ler o Quadro de Caça</b> já aparece. (Na Margem das Memórias o quadro mudou de lugar: estava atrás de uma barraca.)<br><b>Caça automática:</b> quando para, a escolha dos bichos é zerada e o ponto de caça antigo é esquecido. Ao abrir de novo só aparecem os bichos <b>de onde você está</b> (antes o personagem podia sair andando atrás dos bichos do deserto e travar na floresta).' },
    { id: 'n150', data: '25/11', t: '🔢 Barras 2 e 3 não somem mais', d: '<b>Atalhos:</b> o que você coloca nas <b>barras 2 e 3</b> agora fica salvo (antes sumia quando o jogo recarregava). Pode montar de novo que não perde mais.<br><b>Margem das Memórias:</b> quem chegava pela luz caía em cima da fogueira do acampamento e ficava preso. A fogueira mudou de lugar e você chega do lado da luz.' },
    { id: 'n149', data: '25/11', t: '🚪 Saída da Torre e outras correções', d: '<b>Torre:</b> no 1º andar agora tem a placa <b>⬇ SAÍDA</b> na rampa, e quando não tem bicho perto aparece o botão <b>🚪 Sair da Torre</b> (no Abismo, <b>Voltar para a Cratera</b>).<br><b>Chefes não entram mais nas cidades:</b> se você correr para a cidade, o bicho volta para o lugar dele.<br><b>No computador:</b> clicou no chão, o personagem anda até lá e <b>para</b> (antes saía andando atrás do bicho da missão).<br><b>Habilidades não são automáticas:</b> toque no ícone na barra de baixo para usar (só as marcadas como <i>passiva</i> funcionam sozinhas). O jogo agora avisa quem ainda não usou.' },
    { id: 'n148', data: '25/11', t: '💬 Mensagens em tela grande', d: '<b>Toque no quadro de mensagens</b> (o do canto esquerdo) e ele abre <b>grande</b>, com as mensagens de trás: role para cima para ler tudo o que aconteceu (guarda as últimas 250). Toque de novo, ou fora dele, para fechar.' },
    { id: 'n147', data: '25/11', t: '👥 Tela do grupo nova e correções', d: 'O <b>👥 Grupo</b> agora abre numa <b>tela grande</b> com os <b>6 espaços</b> sempre à mostra e o <b>corpo inteiro</b> de cada um (👑 no líder, vida, onde está). Toque num companheiro para trocar, seguir, fazer seguir ou passar a liderança. <b>Seguir na Torre</b>: quem segue agora anda junto também dentro do mesmo andar (antes só se mexia quando o outro trocava de andar). No castelo, as <b>portas ficaram mais largas</b> e as paredes param de "comer" as passagens; o <b>tapete da entrada</b> não pisca mais; a <b>lousa</b> está nítida e encostada na parede. E todas as <b>placas e cartazes</b> do jogo ficaram mais nítidos vistos de lado.' },
    { id: 'n146', data: '25/11', t: '🏰 Câmera do castelo arrumada', d: 'No <b>castelo da guilda</b> a câmera não fica mais presa e colada no personagem: ela fica <b>de longe e um pouco por cima</b>, como nos outros mapas, e o castelo ficou sem teto para dar para ver as salas inteiras. Parede, coluna ou arco que tapar a visão some inteiro. Também diminuí as áreas que travavam o personagem perto das mesas.' },
    { id: 'n145', data: '24/11', t: '🗺️ Mapa do Mundo novo', d: 'O <b>Mapa do Mundo</b> foi redesenhado como um mapa de fantasia: um continente só, com os territórios dividindo fronteiras, litoral, mar, montanhas em Valdora, a Floresta Morta cheia de pinheiros, túmulos e névoa no Vale, o rio do Reino, as estradas e a Torre do Cisma no lugar dela. A <b>Cidade Submersa</b> é um arquipélago flutuando no céu estrelado e o <b>Rio das Memórias</b> aparece num recorte redondo, "sob a Cidade". Toque num território para abrir o mapa dele.' },
    { id: 'n144', data: '24/11', t: '🗺️ Mapa do Mundo desenhado e 🟣 mais baús', d: 'O <b>Mapa do Mundo</b> virou um mapa de verdade, em pergaminho: cada lugar é uma terra com contorno, no lugar certo (a Praia e o mar no oeste, o Reino no meio, Valdora, Floresta e Vale ao norte, as ilhas da Cidade Submersa e o lago do Rio das Memórias no leste), com montanhas, árvores, túmulos, cristais, estradas e rosa dos ventos. Toque numa terra para abrir o mapa dela. E agora tem <b>mais de 20 baús escondidos</b> espalhados por todos os mapas, com prêmio do nível do lugar. Procure o brilho ✦.' },
    { id: 'n143', data: '24/11', t: '👑 Líder do grupo e 🥁 invasão', d: 'O grupo agora tem <b>líder</b> (👑, quem criou). Só o líder tem <b>📢 Todos me sigam</b>: cada um recebe um aviso e tem <b>30 segundos para recusar</b>; se não recusar, começa a seguir sozinho. O líder também pode <b>passar a liderança</b> (👑 no quadro do companheiro). E na <b>Invasão</b>, quem está na cidade invadida ouve uma música de batalha.' },
    { id: 'n142', data: '24/11', t: '💧 Mapa novo: o Rio das Memórias (Nv 86–110)', d: 'Seguindo o livro (cap. 11): depois da Cidade Submersa, pule no <b>redemoinho de água na beira norte de O Fundo</b> e caia no <b>Rio das Memórias</b>, o lago subterrâneo onde <i>"sob a superfície havia milhares de pequenas luzes ... eram memórias"</i>. Na <b>Margem das Memórias</b> acampam a Guardiã Ondina, a Curandeira Iara, o Mascate Tobias do Rio e o Guia de Viagem Caio. Mais adiante: as <b>Galerias Afogadas</b> e a <b>Porta dos Três Espinhos</b>, guardada pelo <b>Guardião Branco</b> (chefe, Nv 110). Monstros novos (Memória Afogada, Lume Errante, Raiz do Rio, Soldado de Memória e Guarda dos Três Espinhos), o <b>Conjunto do Rio das Memórias</b> e a <b>Lança do Guardião Branco</b>. A história continua com a Náufraga Ilene depois de vencer a Sombra da Fonte.' },
    { id: 'n141', data: '24/11', t: '🦀 Caranguejos novos', d: 'O <b>Caranguejo</b> e o <b>Rei Caranguejo</b> da Praia de Cômodo foram refeitos: patas que andam de verdade, pinças que abrem, fecham e beliscam, e olhos nas hastes. E quem cai na Cidade Submersa ou no Rio das Memórias agora volta para a cidade de lá, não para Solmira.' },
    { id: 'n140', data: '24/11', t: '👥 Jogar junto vale em tudo', d: 'XP, missão e itens repartidos do grupo agora valem em <b>todo lugar</b>: campos, Cratera, Torre, Abismo, masmorras e também nos <b>eventos</b> (invasão, caçada do castelo…). Basta estar no <b>mesmo mapa</b> (na Torre, no mesmo andar). Quem está mais de 10 níveis abaixo pega a carona, e cada um vê no chat quanto ganhou.' },
    { id: 'n139', data: '24/11', t: '⚖️ Duelo da Guilda com todos iguais e ✨ Aura dos Irmãos', d: 'No <b>Duelo da Guilda</b> (quinta, 20h) todo mundo fica <b>igual</b>: nível 100, os mesmos atributos, sem equipamento e com <b>todas as habilidades no máximo</b>. Cada rodada tem <b>2 minutos de preparação</b> (sem PvP) para pôr as habilidades na barra e separar as poções, depois <b>5 minutos de luta</b>. A barra do duelo fica guardada para a próxima semana, e ao sair tudo volta ao normal. E quem vestir a <b>Irmandade Eterna completa (8 peças)</b> e tiver o <b>Valtrion</b> ganha a <b>✨ Aura dos Irmãos</b>: um círculo dourado girando no chão que todo mundo vê.' },
    { id: 'n138', data: '24/11', t: '👥 Grupo, seguir e correções', d: '<b>XP do grupo</b>: agora vale para quem está no <b>mesmo mapa</b> (antes era só até 45 m do bicho). O <b>quadro do grupo</b> mostra o retrato de cada um; tocando no quadro abre o menu (trocar, seguir…), com <b>📢 Fazer ele me seguir</b> e <b>📢 Todos me sigam</b>. <b>Seguir</b>: não fica mais indo e voltando quando a pessoa para, e na <b>Torre e no Abismo</b> quem segue (ou o grupo que estava do lado) <b>entra junto</b> e troca de andar junto. O <b>chefe de campo</b> não fica mais imune: enquanto alguém bate nele, ele vai atrás em vez de voltar para casa. O <b>Bestiário</b> tem busca por nome ou nível (ex.: 40 ou 30-50). O personagem não afunda mais no morro, e o andar sozinho só para com a vida abaixo de 30%.' },
    { id: 'n137', data: '24/11', t: '🎁 Drops do grupo, bonecos e comparação justa', d: '<b>Drops do grupo</b>: em cada bicho que cai, o grupo perto recebe <b>um item para cada</b>, na vez de cada um (2 itens e 2 pessoas = 1 para cada; com 3 pessoas, um fica sem). A <b>🃏 Carta do Campeão Sombrio</b> é uma só por vitória e quem pega aparece <b>na tela de todo mundo</b>. No castelo, os <b>bonecos de treino</b> agora têm nível escolhido por você (⚙️ perto do boneco): o primeiro é o <b>👑 Boneco MVP</b>, com defesa de chefe, e os outros têm a defesa de bicho comum. E a <b>comparação de equipamento</b> na mochila agora conta o <b>bônus de conjunto</b>: trocar uma peça da Irmandade Eterna (8 peças) por outra mostra quanto se perde do bônus.' },
    { id: 'n136', data: '24/11', t: '🐉 Campeão Sombrio: um só por terça', d: 'O <b>Campeão Sombrio</b> agora aparece <b>uma vez</b> por terça, às 20h, e fica até 20h30. Se a guilda não derrubar, ele vai embora. Como é um só, cada vitória dá <b>3 🎖️ Emblemas</b> para quem ajudou (trocam pelas peças com o Capitão da Guarda de Auren). A <b>🃏 Carta do Campeão</b> é <b>uma só por vitória</b> e só na sorte: quando ele cai, o jogo sorteia se a carta cai e para quem, entre os que bateram, e todo mundo vê quem levou.' },
    { id: 'n135', data: '24/11', t: '👆 Tocar no jogador e o Capitão de Auren', d: 'Tocar em <b>outro jogador</b> (no boneco ou no nome) para abrir o menu dele (convidar para grupo, guilda, seguir, emoji…) ficou mais fácil de acertar. E o guarda que troca os emblemas do Campeão agora é o <b>Capitão da Guarda de Auren</b>, que serviu na cidade no dia em que o céu rachou.' },
    { id: 'n134', data: '24/11', t: '🐉 MVP da guilda: Campeão Sombrio', d: 'Toda <b>terça às 20h</b> (20h00, 20h10 e 20h20) o <b>Campeão Sombrio</b> invade o castelo e a guilda inteira enfrenta o mesmo chefe. <b>Cada um que ajudou</b> sorteia o próprio saque: o novo <b>Conjunto do Campeão Sombrio</b> (lâmina, elmo, couraça, manoplas e grevas) e a <b>🃏 Carta do Campeão Sombrio</b> só caem dele. A carta é única: além de atributos, dá <b>+10% de todo o dano</b> (até <b>+25%</b> na Suprema). E não fica só na sorte: cada vitória dá <b>1 🎖️ Emblema do Campeão</b> para todos que ajudaram, e o <b>Capitão da Guarda de Auren</b> (no arsenal) troca emblemas pela carta (40) ou pelas peças (15 a 25).' },
    { id: 'n133', data: '24/11', t: '🏰 Castelo arrumado e brincadeiras novas', d: 'O castelo da guilda não fica mais "bugado": a câmera fica dentro da sala (sem paredes transparentes nem o vazio preto). Brincadeiras das 20h, uma diferente por dia: <b>seg</b> ⚔️ Caçada no Saguão · <b>ter</b> 🐉 <b>Chefe da Guilda</b> (o Campeão Sombrio aparece às 20h00, 20h10 e 20h20 e a guilda inteira enfrenta o MESMO chefe) · <b>qua</b> 🎁 Baús Escondidos · <b>qui</b> 🗡️ <b>Duelo da Guilda</b> (PvP entre a guilda, rodadas de 5 minutos; quem cai volta no saguão sem perder nada) · <b>sex</b> 🎯 <b>Desafio dos Bonecos</b>. Os <b>bonecos do arsenal</b> agora são de treino: dá para bater e eles mostram o dano por segundo. E o <b>Bobo</b> joga jokenpô a qualquer hora (vitória dá coroas).' },
    { id: 'n132', data: '24/11', t: '📜 Habilidades com Confirmar e outras correções', d: 'Na janela de <b>habilidades</b>, os pontos só valem depois de tocar em <b>✅ Confirmar</b> (dá para <b>↩️ Desfazer</b>). As caixas ficaram menores para ver o caminho todo, e tocando numa habilidade aparece o que ela faz. A <b>Chuva de Estrelas</b> agora dura <b>5 minutos</b>. O <b>chefe que volta para casa</b> fica <b>imune</b> e se cura (não dá mais para matar de longe enquanto ele está parado no limite). <b>Tocar no boneco</b> de outro jogador também abre o menu dele (convidar para grupo e guilda). E o chat com o teclado aberto ficou mais transparente.' },
    { id: 'n131', data: '24/11', t: '🌍 O mundo é o mesmo: Torre, Abismo e masmorras', d: 'Agora <b>todo mundo vê os mesmos monstros</b> na <b>Torre</b>, no <b>Abismo</b> e nas masmorras (<b>Mina</b>, <b>Cripta</b>…), <b>com grupo ou sem</b>. Quem chega num andar entra na mesma luta de quem já está lá. Na masmorra, se alguém já está lá dentro, você entra na corrida dele (mesmo nível e mesmo relógio). Só o <b>Templo do Eco</b> continua separado por grupo, por causa dos quebra-cabeças.' },
    { id: 'n130', data: '24/11', t: '🍼 Carona proporcional e missões', d: 'A carona do grupo agora é <b>proporcional</b>: quanto mais abaixo de quem matou, mais XP você ganha por bicho, para <b>encostar</b> no nível dos amigos (11 níveis abaixo: até 0,45% de um nível por bicho; 20 abaixo: 0,9%; 40 abaixo: 1,9%; 60 ou mais: 2,9%). E o bicho que o grupo mata <b>perto de você</b> agora <b>conta nas suas missões</b> e no bestiário: é só ir ao mapa e ficar junto. Itens e coroas continuam só para quem mata.' },
    { id: 'n129', data: '24/11', t: '📖 Livro dos Móveis e baú nas entregas', d: 'Novo <b>📖 Livro dos Móveis</b> (no ☰ Mais, com a Governanta Clara ou com o Mestre de Obras): todos os móveis da casa, cômodo por cômodo, os que faltam aparecem apagados e cada linha completa ganha ★. E para fazer móveis e cômodos agora vale o que está no <b>baú da casa</b> também: aparece quanto tem na 🎒 mochila e no 📦 baú, separado, e você escolhe de onde sai primeiro. Seguir alguém em <b>outro mapa</b> também só avisa e não anda.' },
    { id: 'n128', data: '24/11', t: '🍼 Carona de XP e 🗼 Torre em grupo', d: 'Em <b>grupo</b>, quem está <b>mais de 10 níveis abaixo</b> pega <b>carona</b>: quando o companheiro mais forte mata <b>perto</b> de você, você ganha um pouco de XP (até <b>0,8% de um nível por bicho</b>), e quem matou <b>não perde nada</b>. Missões e itens continuam valendo só para quem caça. E a <b>Torre e o Abismo em grupo</b> agora são <b>o mesmo andar para todos</b>: os mesmos monstros, a escadaria abre junto e um andar que o grupo já limpou fica aberto para quem chega depois.' },
    { id: 'n127', data: '24/11', t: '📖 Cômodo completo = ponto de atributo', d: 'Completou os <b>5 móveis</b> de um cômodo da casa? Ganha <b>+1 ponto de atributo</b> e uma <b>placa dourada</b> no cômodo. Os <b>8 móveis da sala</b> também contam. A casa inteira vale <b>9 pontos</b>, e eles <b>não se perdem</b> ao resetar os atributos. Quem já tinha cômodo completo recebe o ponto ao entrar no jogo.' },
    { id: 'n126', data: '24/11', t: '🏰 Castelo da guilda e brincadeiras às 20h', d: 'No painel da <b>guilda</b> (agora com abas) tem <b>🏰 Entrar no castelo</b>: saguão, vestíbulo, arsenal, salão de banquete e biblioteca, com o estandarte da guilda e gente andando lá dentro. <b>De segunda a sexta às 20h</b> tem brincadeira da guilda no castelo (30 min): caça aos invasores, <b>jokenpô com o Bobo</b> e <b>baús escondidos</b> pelas salas. Os pontos viram prêmios e ajudam a guilda.' },
    { id: 'n125', data: '24/11', t: '👥 Grupo novo e masmorra só com aceite', d: 'O painel do <b>grupo</b> ficou novo. Quando o <b>líder</b> pede para entrar numa masmorra em grupo, <b>todos precisam aceitar</b>; se alguém recusar, <b>ninguém entra</b>. E agora dá para <b>tocar no nome de outro jogador</b> para abrir um menu: ver perfil, <b>seguir</b>, trocar, mandar <b>emoji</b>, chamar para o grupo ou para a guilda.' },
    { id: 'n124', data: '24/11', t: '📣 Avisos grandes e correções', d: 'Eventos, Kravenox, Verme, Guerra e brincadeiras da guilda agora aparecem <b>grandes na tela</b>, com aviso 5 minutos antes. Corrigido: o aviso falso de <b>"Sua conta entrou em outro aparelho"</b> depois que a internet volta (e se acontecer, tem o botão <b>Continuar jogando aqui</b>), o personagem que <b>passava pelas cercas</b> do Sítio e o andar sozinho/seguir que <b>travava</b> em tendas e casas. Seguir alguém que está na Torre, no Abismo, numa masmorra ou numa casa agora avisa <b>"esse mapa não dá para seguir"</b> (antes saía andando pelo mato). E o <b>chat no celular deitado</b>: com o teclado aberto, a conversa e a caixa de texto ficam no espaço que sobra, acima do teclado.' },
    { id: 'n123', data: '24/11', t: '🎤 Rádio do grupo saiu', d: 'O botão 🎤 de recados de voz do grupo foi tirado: para conversar por voz, usem o <b>Discord</b>. O chat de texto 💬 continua igual.' },
    { id: 'n122', data: '24/11', t: '🔧 Botão AUTO e microfone', d: 'O botão <b>AUTO</b> mudou para o lado do <b>joystick</b> (no canto direito ele ficava por cima do quadro de missões). E o 🎤 rádio do grupo agora explica <b>por que</b> o microfone não abriu e <b>como liberar</b>. No iPhone: toque em <b>aA</b> na barra de endereço do Safari → <b>Ajustes do Site</b> → <b>Microfone</b> → <b>Permitir</b>; se o jogo está na Tela de Início, vá em <b>Ajustes → Safari → Microfone</b>.' },
    { id: 'n121', data: '24/11', t: '🏗️ Casa gigante, horta e curral melhores', d: 'Ao lado da sua casa, o <b>Mestre de Obras Tibério</b> constrói <b>8 cômodos novos</b> (Quarto Real, Biblioteca Arcana, Sala de Troféus, Cozinha e Adega, Ateliê, Jardim de Inverno, Salão Nobre e Observatório Estelar), um depois do outro, pela porta do lado oeste da sala. Cada cômodo tem <b>5 móveis</b> que pedem coroas e <b>muito material</b> de caçada. Todo móvel dá <b>Conforto</b>: ao sair de casa você fica <b>1 hora 🏠 Descansado</b>, com bônus de <b>XP, drop e coroas</b> que crescem com o conforto. Lá dentro, a <b>Governanta Clara</b> varre a casa e avisa quais móveis você já pode fazer. No Sítio, a <b>Fazendeira Dália</b> agora melhora a <b>horta</b> e o <b>curral</b> (até o nível 5: mais rápido, mais colheita e mais vagas), e os animais ganharam um jeito novo de andar: pastam, ciscam, aceleram e viram com calma.' },
    { id: 'n120', data: '24/11', t: '📦 Baú da casa novo', d: 'O <b>baú da casa</b> agora funciona como a mochila: <b>abas</b> (Equip., Material, Cartas, Usáveis, Sítio), ícones novos, detalhes do item e botões para guardar ou pegar <b>1, 10, a quantidade que quiser ou tudo</b>. E dá para <b>guardar ou pegar tudo de uma aba</b> de uma vez (ex.: todo o material). Peças presas e a montaria ficam sempre com você.' },
    { id: 'n119', data: '24/11', t: '⚔️ Masmorras com 5 níveis', d: 'A <b>Mina da Forja</b>, a <b>Cripta das Cartas</b> e o <b>Templo do Eco Selado</b> agora têm <b>5 níveis de dificuldade</b>: <b>1 Aprendiz</b> (Nv 20+), <b>2 Veterano</b> (Nv 50+), <b>3 Mestre</b> (Nv 80+), <b>4 Lendário</b> (Nv 110+) e <b>5 Impossível</b> (Nv 150+). Quanto mais alto, mais fortes os monstros e <b>maior o saque</b> (até ×4,8). Nos 🏆 <b>Recordes</b> aparece o selo do nível (N1 a N5), e quem fez num nível mais alto fica na frente. E na 🤖 caça automática dá para escolher <b>até onde ele vai</b> (de 10 a 200 m).' },
    { id: 'n118', data: '24/11', t: '🎨 Ícones novos dos equipamentos', d: 'Todos os equipamentos ganharam <b>ícones desenhados</b> no lugar dos emojis: espadas, arcos, cajados, garras, elmos, capuzes, coroas, armaduras, mantos, luvas, botas, anéis e colares, com metal brilhante, gemas e as cores do material de cada peça (névoa, cristal, sombra, ouro, raiz, osso, primordial...). A cor de fundo mostra a raridade.' },
    { id: 'n117', data: '24/11', t: '⚔️ Portão novo da Arena', d: 'A entrada da <b>Arena de Solmira</b> (Mestre Brakus) virou um portal de coliseu de verdade: colunas com anéis de ouro, arco de pedra, espadas cruzadas no escudo, estandartes, braseiros acesos e a luz dourada dentro do arco.' },
    { id: 'n116', data: '24/11', t: '🔢 Atalhos melhores', d: 'Ao tocar em <b>📌 Pôr no atalho</b> (na mochila ou nas habilidades), agora você escolhe <b>em qual barra</b> vai: 1, 2 ou 3 (com quantos espaços livres cada uma tem). E no modo <b>✏️</b>, <b>segure um atalho e arraste</b> para o espaço que quiser: os dois trocam de lugar.' },
    { id: 'n115', data: '24/11', t: '🏆 Recordes com os 5 primeiros e botão AUTO', d: 'O 🏆 <b>Recordes</b> (☰ Mais) já mostra os <b>5 primeiros</b> de cada lugar, em tempo e em dano. No celular, a caça automática agora é o botão redondo <b>AUTO</b> ao lado do ataque (fica verde e pulsando enquanto caça; toque de novo para parar). E as setas que encolhem os quadros ficaram mais bonitas.' },
    { id: 'n114', data: '24/11', t: '🛡️ Novo amigo: Balhulk', d: 'O cavaleiro <b>Balhulk</b> chegou ao <b>Acampamento de Valdora</b> com uma aventura de <b>7 provas</b> (está na lista 🤝 Amigos). O que ele dá no final? Ninguém sabe. Ele só diz que é algo que <b>ninguém neste Reino tem</b>... Quem completar, descobre.' },
    { id: 'n113', data: '24/11', t: '🤖 Caça automática', d: 'Para quem não tem tempo: vá até um mapa de caça e toque em <b>🤖</b> lá em cima. Escolha <b>os bichos</b>, <b>as habilidades</b> que ele vai usar e <b>quando tomar poção</b> de vida e de SP (e quando parar se acabar a poção). Toque em <b>Começar</b> e o personagem caça sozinho até 30 m de onde você está, se defendendo de quem atacar. Ele usa a <b>maior poção liberada</b> para o seu nível. Para parar, é só mexer o personagem (ou tocar em 🤖 → Parar). Os mapas são difíceis: leve bastante poção!' },
    { id: 'n112', data: '24/11', t: '⚗️ Oficina do Doran: materiais valem algo', d: 'Os materiais de monstro agora têm destino: fale com o <b>Ferreiro Doran</b> → <b>⚗️ Oficina</b>. Cada material vira <b>pontos de ofício</b> (o <b>dobro</b> do que o Mercador paga), e os pontos viram <b>Pó de Forja, Minério Rúnico, Pedra de Têmpera, Fragmento Arcano, Fragmento do Cisma, poções médias, Núcleo do Abismo e Selo da Forja</b>. Dá para entregar tudo ou só o excesso (guarda 10 de cada, para as receitas de equipamento).' },
    { id: 'n111', data: '24/11', t: '📚 Livro das Regiões', d: 'No 📖 <b>Bestiário</b> (☰ Mais), toque em <b>📚 Regiões</b>. Cada região do mapa tem <b>5 estrelas</b>: ★1 derrote <b>todos os tipos</b> de bicho da região · ★2 <b>100 de cada</b> · ★3 <b>500</b> · ★4 <b>1.500</b> · ★5 <b>5.000</b>. Cada estrela dá um prêmio (fragmentos, núcleos...), maior nas regiões mais fortes, e na ★4 e ★5 vem uma <b>carta de um bicho da região</b>. Quem já caçou muito ganha as estrelas atrasadas no próximo abate naquela região!' },
    { id: 'n110', data: '24/11', t: '☰ Barra de cima mais curta e 3 barras de atalho', d: 'A barra de cima batia no quadro do personagem e no mapa. Agora ficam só os botões mais usados, e o resto (Atributos, Bestiário, Sentar, Música, Recordes, Loja de Visuais, Guilda e Ajuda) está no novo botão <b>☰ Mais</b>. Os <b>📊 Atributos</b> também abrem tocando no <b>quadro do seu personagem</b> (vida e SP). E ao lado do ✏️ da barra de baixo há um botão com um <b>número</b>: ele troca entre <b>3 barras de atalho</b> (ex.: habilidades na 1 e poções na 2).' },
    { id: 'n109', data: '24/11', t: '❤️‍🩹 Poções maiores e fusão de poções', d: 'Novas poções que curam uma parte da vida ou do SP <b>máximo</b>: <b>Média</b> (20%, Nv 40+), <b>Grande</b> (35%, Nv 60+) e <b>Gigante</b> (60%, Nv 80+), vermelhas e azuis. O <b>Mercador Bento</b> vende em “Poções maiores”. E na 🎒 mochila, toque numa poção: <b>10 de um tamanho se fundem em 1 do tamanho seguinte</b> (“Fundir todas” faz tudo de uma vez). Quem tem milhares de poções pequenas agora tem poções de verdade!' },
    { id: 'n108', data: '24/11', t: '📋 Quadros de Caça: 2 por cidade', d: 'Antes eram 6 contratos por dia somando todos os quadros. Agora <b>cada Quadro de Caça dá 2 contratos por dia</b>: para fazer mais, viaje e pegue nos quadros das <b>outras cidades</b> (são 8). O quadro mostra quantos você já pegou ali e quais cidades ainda têm contrato hoje. E mais: a confirmação do ♻️ <b>Resetar</b> agora aparece na frente da janela, e os fantasminhas da Erya voltaram ao normal (sem o círculo e a coluna de luz por cima).' },
    { id: 'n107', data: '24/11', t: '🏛️ Templo mais difícil e sempre diferente', d: '<b>Ponte que Desaba:</b> agora tem <b>dois vãos</b> sem pedra nenhuma, em lugares sorteados: só passa quem <b>pular</b> (⤴). <b>Quatro Alavancas:</b> a ordem é sorteada a cada entrada (24 possibilidades) e a parede dá só duas pistas. Errar faz as alavancas voltarem e chama criaturas, mas a ordem <b>não muda</b>: quem errou aprendeu algo. Só muda quando você entra de novo no Templo. <b>Luz dos Espelhos:</b> o salão pode vir espelhado e o espelho falso muda de lugar, então a solução decorada não serve.' },
    { id: 'n106', data: '24/11', t: '🌠 Chuva de Estrelas nova', d: 'As estrelas agora <b>caem do céu de verdade</b>, com rastro de brilho e um círculo no chão mostrando onde vão cair. <b>1 em cada 8 é uma estrela rara</b> 🌠 (azul e maior), com prêmio bom: Núcleo do Abismo, fragmentos de carta, Selo da Forja ou até uma Lágrima do Soberano. E a cada 5 segundos uma estrela <b>cai em cima do monstro mais perto</b> de você, com dano forte em volta. Só para quem está caçando fora das cidades.' },
    { id: 'n105', data: '24/11', t: '✨ Chuva de Estrelas mais justa', d: 'Na <b>Chuva de Estrelas</b> (evento surpresa), as estrelas caíam até em quem estava parado na cidade. Agora elas só caem para quem está <b>caçando fora das cidades</b> (andando no último meio minuto), e no máximo <b>15 por pessoa</b> em cada evento.' },
    { id: 'n104', data: '24/11', t: '✨ Magias de área novas', d: 'Várias magias de área só desenhavam um círculo no chão. Agora cada uma tem efeito próprio: na <b>Erya</b>, espíritos mergulham do céu (Mil Possibilidades, Todas as Escolhas, Destino Quebrado) e giram em redemoinho (Tormenta); na <b>Seraphyne</b>, esferas negras do Vazio que puxam tudo e implodem, e correntes roxas (Portal, Silêncio, Esfera, Correntes, Apagar, Buraco Negro, Fim de Tudo); na <b>Mãe</b>, correntes brancas, cortes de lua e o chão tremendo (Correntes Brancas, Voltem, Grito, Passos que Tremem); no <b>Kravenox</b>, o Rugido e as quatro colunas da Quarta Essência.' },
    { id: 'n103', data: '24/11', t: '🔧 Ponte do Templo e saída da Arena', d: '<b>A Ponte que Desaba</b> (Templo do Eco Selado): a pedra firme desabava embaixo de você antes de dar tempo de atravessar, e ninguém passava. Agora ela só desaba <b>atrás</b> de você, depois que você sai dela (ou se ficar parado nela tempo demais: ela treme antes). As runas também ficam acesas um pouco mais. <b>Arena:</b> ao sair, você aparecia em cima do Mestre Brakus e ficava preso; agora aparece ao lado dele. As saídas de todas as masmorras procuram um lugar livre.' },
    { id: 'n102', data: '23/11', t: '🥽 VR no Meta Quest (experimental)', d: 'No navegador do <b>Meta Quest</b>, aparece um botão <b>🥽</b> lá em cima: você entra no jogo em realidade virtual, olhando em volta com a cabeça, com o herói andando à sua frente. Analógico esquerdo anda, gatilho direito ataca, A e B usam habilidades, analógico direito gira a vista. Ainda é um teste: vida e mochila não aparecem nos óculos. No celular e no PC nada muda.' },
    { id: 'n101', data: '23/11', t: '🏰 Guerra de Guildas', d: 'Todo <b>domingo, das 18h às 19h</b>, a <b>Fortaleza das Bandeiras</b> abre (Comandante Varek, ao sul da praça de Solmira; só membros de guilda). No meio dela está o 💎 <b>Coração da Fortaleza</b> (2 milhões de vida, o mesmo para todos). PvP livre contra as outras guildas, <b>sem perder XP nem itens</b>. A guilda que causar <b>mais dano</b> no Coração <b>domina a Fortaleza</b> até a guerra seguinte: <b>+10% de XP e de drop</b> para todos os membros. Também está no 🏰 Masmorras.' },
    { id: 'n100', data: '23/11', t: '⚔️ Arena de Solmira e ponte do Templo consertada', d: '<b>⚔️ Arena</b> (Mestre Brakus, a leste da praça de Solmira, nível 15+): PvP livre num coliseu, <b>sem penalidade</b> (morrer lá não tira XP nem itens, nem de quem está vermelho; você volta na porta com a vida cheia). Cada vitória conta para o <b>🏆 placar da temporada</b> (um mês), também em 🏆 Recordes. <b>Templo, A Ponte que Desaba:</b> havia um vão invisível entre as pedras e, andando, sempre se caía; agora as pedras ficam encostadas e passar pela quina de uma pedra falsa não derruba. <b>Masmorras</b> (Mina, Cripta e Templo) agora são <b>seguras</b> como as cidades: ninguém ataca ninguém lá dentro. O PK continua igual no resto do mundo.' },
    { id: 'n99', data: '23/11', t: '⚡ Eventos surpresa, 👘 trajes de classe e evolução nova', d: '<b>⚡ Eventos</b>: toda hora, dos 30 aos 50 minutos, acontece um: <b>🌟 Hora Dourada</b> (+50% de XP e drop), <b>⚔️ Invasão</b> (monstros atacam uma cidade e soltam fragmentos), <b>✨ Chuva de Estrelas</b> (estrelas com prêmio caem perto de você) ou <b>🧳 Mercador Orlo</b> (vende raridades numa praça). Avisa 2 minutos antes. <b>👘 Trajes de classe</b> (📅 Tarefas → Trajes): Alvorada, Abismo e Soberano, cada um com a sua missão; é um brilho na cor do traje que todos veem. <b>✨ Evolução de classe</b> mais marcante: luz, tremor e a marca da classe no corpo. <b>Habilidades fortes</b> (nível 12 e da 2ª/3ª classe) com efeito novo. <b>Templo</b>: as salas vêm em ordem sorteada. <b>Masmorras</b>: o painel não cobre mais a vida do chefe.' },
    { id: 'n98', data: '23/11', t: '📅 Tarefas do dia, 🎓 tutorial e 📈 medidor', d: '<b>📅 Tarefas</b> (ícone novo lá em cima): 3 por dia e 1 por semana, com prêmio (XP, coroas, poções, fragmentos e Selo). Fazendo as 3 do dia, ganha um <b>bônus</b>. <b>🎓 Tutorial</b> para quem é novo (até o nível 10): mostra passo a passo como andar, lutar, usar a mochila, as missões, as tarefas, as masmorras e o grupo; dá para pular. <b>📈 Medidor de desempenho</b> (menu ❓): mostra os quadros por segundo no canto da tela e, tocando nele, o relatório dos lugares onde o jogo ficou mais lento. Se travar, tire um print e mande para o Claude.' },
    { id: 'n97', data: '23/11', t: '🏰 Masmorras e 🏆 Recordes lá em cima', d: 'Dois ícones novos na barra de cima: <b>🏰 Masmorras</b> reúne todas (Templo, Cripta, Mina, Torre e Abismo) com o nível, as entradas que restam na semana e o botão <b>🧭 Ir até lá</b>; <b>🏆 Recordes</b> reúne todos os rankings de tempo e de dano.' },
    { id: 'n96', data: '23/11', t: '🏛️ Templo do Eco Selado e 🏆 Ranking', d: 'Na entrada de pedra ao sul da praça de Solmira, a <b>Estudiosa Ilka</b> abre o <b>Templo do Eco Selado</b> (nível 30+, 3 vezes por semana): uma masmorra de <b>armadilhas e enigmas</b>, não de matar monstro. 6 salas: <b>o Piso que Lembra</b> (decore as placas que brilham), <b>o Corredor das Lâminas</b> (use a esquiva), <b>as Quatro Alavancas</b> (resolva a charada), <b>a Luz dos Espelhos</b> (leve o raio ao cristal), <b>a Ponte que Desaba</b> (decore as runas e não pare) e <b>o Guardião do Eco</b> (imune até os 4 pilares estarem acesos juntos). Conta o <b>tempo</b> e as <b>quedas</b>: baú de 🥇 ouro, 🥈 prata ou 🥉 bronze, e o título « Decifrador do Eco » no primeiro ouro. Em grupo, as alavancas vão em dupla e o baú é maior. <b>🏆 Ranking</b> de <b>tempo</b> e de <b>dano</b>: Templo, Mina, Cripta (no NPC de cada uma) e placas na porta da <b>Torre</b> (1º andar ao topo) e na boca da <b>Cratera</b> (1º andar ao Fundo).' },
    { id: 'n95', data: '23/11', t: '⚡ Jogo mais leve e limite semanal das masmorras', d: '<b>Travamento:</b> a Mina, a Cripta, a tenda da Zaíra e a Casa ficavam com as luzes acesas o tempo todo, mesmo com você longe, e isso pesava no mapa inteiro. Agora elas só existem quando você está dentro. <b>Limite por semana</b> (vira na segunda-feira, sozinho ou em grupo): <b>Cripta das Cartas 2 vezes</b> e <b>Mina da Forja 5 vezes</b>. O NPC mostra quantas restam. <b>Floresta Morta:</b> as árvores perderam os cristais roxos do tronco. <b>Guerreiro Cristalizado:</b> se aparecer com o desenho antigo, vira 3D em até 2 segundos.' },
    { id: 'n94', data: '22/11', t: '🃏 Tenda da Zaíra e ícones maiores', d: 'A <b>Cartomante Zaíra</b> agora tem uma <b>tenda roxa</b> a oeste da praça de Solmira (antes estava colada no Quadro de Caça). Os <b>ícones em cima dos NPCs</b> ficaram maiores (o dela é uma carta 🃏). <b>Cripta e Mina:</b> você não cai mais em cima do arco de saída ao entrar.' },
    { id: 'n93', data: '22/11', t: '👥 Masmorras em grupo (até 6)', d: 'A <b>Mina da Forja</b> (Ferreiro Doran) e a <b>Cripta das Cartas</b> (Cartomante Zaíra) agora têm dois jeitos: <b>sozinho</b> (como antes) ou <b>👥 em grupo</b>, de 2 a 6 pessoas. Em grupo todos veem e batem nos <b>mesmos monstros</b>, que são <b>mais fortes e em maior número</b> (mais ainda quanto maior o grupo), e o <b>saque é bem maior</b>, dividido entre o grupo. Como fazer: monte o grupo no 👥, um fala com o NPC e escolhe <b>em grupo</b>; os outros falam com o mesmo NPC e escolhem <b>Entrar com o seu grupo</b>. <b>Grupo consertado:</b> desde a versão 27 os companheiros não estavam sendo reconhecidos (XP e itens não se dividiam); já voltou ao normal.' },
    { id: 'n92', data: '22/11', t: '💔 Cartomante Zaíra: montar e quebrar cartas', d: '<b>Montar:</b> com 🧩 <b>Fragmentos Arcanos</b> (da Cripta das Cartas), a Zaíra monta a <b>carta de monstro</b> que você escolher, por peça. É caro de propósito: de <b>310 a mais de 3.000 🧩</b> (carta de chefe, o triplo). A carta sai Simples e, às vezes, Forte, Invocada ou Suprema. As <b>Cartas Arcanas</b> ela não monta: só caem na Cripta. <b>Quebrar:</b> carta que não serve vira fragmento: Simples 4, Forte 12, Invocada 35, Suprema 100, Arcana 150 (carta de chefe, o dobro). Tem botão para quebrar <b>todas as Simples</b> de uma vez.' },
    { id: 'n91', data: '22/11', t: '🃏 Cripta das Cartas e Cartas Arcanas', d: 'Na <b>Vila de Solmira</b> chegou a <b>Cartomante Zaíra</b>. Ela guarda as <b>Cartas Arcanas</b>, 8 cartas novas que <b>nenhum monstro do mundo solta</b> (Lâmina do Eclipse, Olho que Tudo Vê, Pele do Vazio, Mãos do Ferreiro Antigo, Passo do Vento Rubro, Pacto de Sangue, Estrela Errante e Coração da Essência). Ela manda você para a <b>Cripta das Cartas</b> (nível 30+): 8 minutos, 3 ondas e o <b>Guardião das Cartas</b>. Lá caem <b>🧩 Fragmentos Arcanos</b> e, muito raramente, a carta pronta. As Arcanas só saem como drop raro da Cripta.' },
    { id: 'n90', data: '22/11', t: '🃏 Encaixar carta direto na peça', d: 'Na mochila, toque na peça que você está usando: aparece <b>🃏 Encaixar carta</b> (ou <b>Trocar carta</b>) com a <b>lista só das cartas que cabem nela</b>, das mais fortes para as mais fracas, cada uma com o que dá. Toque numa e pronto: a que estava lá volta para a mochila.' },
    { id: 'n89', data: '22/11', t: '⚒️ Desmontar todos e Guerreiro em 3D', d: '<b>Mochila:</b> quando tem várias peças iguais, aparece <b>⚒️ Desmontar todos</b>: vira tudo em Pó de Forja de uma vez (a peça que você está usando não entra). <b>Guerreiro Cristalizado</b> (chefe de campo das Areias Rubras) agora é <b>3D</b>, feito com IA (Meshy). <b>Material de refino:</b> fale com o <b>Ferreiro Doran</b>, na Vila de Solmira, e escolha <b>⛏️ Descer à Mina da Forja</b>.' },
    { id: 'n88', data: '22/11', t: '🐛 Verme Colossal: hoje, 20h, no Fundo da Cratera', d: 'O Verme acorda <b>hoje (domingo) às 20h</b> no Fundo do Abismo do Cisma e fica 2 horas. É o chefe <b>mais impossível do jogo</b>: <b>4 milhões de vida</b> dividida entre todos (antes a vida de cada um era separada: estava quebrado), <b>🛡️ Escudo do Abismo</b> como o do Kravenox (sozinho, só 5% do dano entra; com 8 no Fundo o escudo cai), golpes que atravessam a defesa, <b>crias</b> saindo da terra a cada vez que ele emerge e <b>fúria</b> abaixo de 40%. <b>Prêmio: a raridade nova 🟢 PRIMORDIAL</b>, acima do Mítico e só dele: Presa Primordial (ataque 185), Carapaça, Bocarra, Anel do Ninho e Coração do Verme, com o <b>Conjunto Primordial</b> (5 peças: +150 ataque, +120 defesa, +2.400 de vida). Também dá Núcleos, Fragmentos, Selos e uma Lágrima do Soberano. <b>Abismo:</b> a esquiva lá dentro vai no máximo a 30% (antes 60%: os monstros quase nunca acertavam) e os guardiões batem bem mais forte.' },
    { id: 'n87', data: '22/11', t: '✨ Despertar ★: o melhor equipamento ainda pode ficar melhor', d: 'Quem já tem as peças Míticas agora tem por que voltar à Torre, ao Abismo e ao Kravenox: com o <b>Ferreiro Doran</b> (✨ Despertar equipamento) cada peça sobe de <b>★1 a ★10</b>, e cada estrela soma <b>8% de TODOS os atributos</b> dela (no ★10, +80%), junto com o refino. Materiais: <b>🔺 Fragmento do Cisma</b> (guardiões e andares altos da <b>Torre</b>), <b>🌑 Núcleo do Abismo</b> (só no <b>Abismo</b>) e <b>🩸 Lágrima do Soberano</b> (só do <b>Kravenox</b>, toda semana). Se falhar, perde os materiais, mas a peça não quebra. A Torre e o Abismo também passaram a soltar <b>🔶 Minério</b>, <b>🔷 Têmpera</b> e <b>🔰 Selo da Forja</b> para o refino até +15.' },
    { id: 'n86', data: '22/11', t: '☠ Kravenox agora é para MUITA gente junta', d: 'O Ludi derrubou o Kravenox sozinho, e um chefe semanal não pode ser assim. Agora: <b>🛡️ Escudo do Cisma</b>: quanto menos gente na arena, menos dano ele sente (sozinho, só <b>5%</b>; com 4, 42%; com <b>8 ou mais o escudo cai</b>). A barra dele mostra quantos estão na arena. <b>Vida:</b> 5 milhões. <b>Golpes</b> muito mais fortes, que atravessam a defesa, e a esquiva quase não salva: <b>fuja dos círculos</b>. Generais do Cisma e servos bem mais duros. <b>Visual novo:</b> o Kravenox agora é a criatura de espinhos em 3D (o desenho pixelado gigante ficava borrado) e os <b>meteoros</b> são rochas em brasa com rastro de fogo. <b>🕳️ Abismo do Cisma</b> muito mais perigoso: monstros com quase 3x a vida, mais ataque e mais monstros por andar. <b>🐾 Mascote:</b> anda no seu passo e não afunda mais na escada.' },
    { id: 'n85', data: '21/11', t: '✕ Botão de fechar nas janelas', d: 'As janelas de conversa, o diário e os quadros agora têm um <b>✕ no canto de cima</b>: não precisa mais rolar até o "Fechar" no meio da luta. No controle, o <b>B</b> continua fechando. <b>Diário:</b> quando os 6 contratos de caça do dia já foram usados, eles não aparecem mais como disponíveis (voltam amanhã).' },
    { id: 'n84', data: '21/11', t: '🚶 Andar até a missão e bater ao mesmo tempo', d: 'Agora, depois de tocar numa missão para ir até ela, você pode <b>atacar e usar habilidades sem parar de andar</b>: o herói vai batendo nos monstros pelo caminho (anda mais devagar só no instante do golpe). Ele ainda <b>para sozinho se a vida cair abaixo da metade</b>, para você não morrer no caminho. Mexer no analógico continua parando a caminhada.' },
    { id: 'n83', data: '21/11', t: '☠ Kravenox renasceu: o maior espetáculo da semana', d: 'Hoje, <b>sábado às 20h</b>, no <b>topo da Torre do Cisma</b>, Kravenox acorda <b>muito mais forte</b>: <b>nível 90</b> e <b>900 mil de vida</b> (dividida entre todos os jogadores). A luta tem <b>4 fases</b>: <b>🌋 O Despertar do Abismo</b> (70%: ele chama 2 <b>Generais do Cisma</b> e servos, e começa a <b>☄️ Chuva de Meteoros</b>), <b>🔥 A Fúria do Soberano</b> (40%: <b>raio triplo</b>, garras duplas, <b>⛓️ Correntes do Cisma</b> que te puxam e o <b>🌑 Eclipse</b>: só quem estiver num <b>círculo de luz dourada</b> escapa) e <b>☠ O Último Suspiro</b> (15%: os <b>Ecos do Soberano</b> e meteoros sem parar). A tela treme nos golpes grandes. Para ganhar o prêmio é preciso causar pelo menos <b>4.500</b> de dano. Vão juntos!' },
    { id: 'n82', data: '21/11', t: '⚔️ Mais difícil no nível alto (pedido do Ludi)', d: '<b>Defesa não zera mais o golpe:</b> antes, com equipamento refinado, a defesa passava do ataque dos monstros e cada golpe tirava 1 de vida. Agora todo golpe tira pelo menos 40% do ataque do monstro. <b>XP:</b> do nível 30 em diante cada nível pede mais experiência (no 55, 2,7 vezes; no 79, 4 vezes), e quem já está alto não perde nível. <b>👾 Mini chefes chamam ajudantes:</b> Guardiões da Torre e do Abismo, alfas, chefes de campo e o Capataz da Mina chamam até 3 crias de cada vez quando a luta começa (no máximo 6 juntas); quando o chefe cai, as crias somem.' },
    { id: 'n81', data: '21/11', t: '🔄 Tela que congelava pela metade', d: 'Quando o celular fica sem memória de vídeo, a imagem do jogo congelava (metade da tela parada) e só o chat continuava funcionando, como aconteceu com a Lady Ingrid na Ponte dos Mortos. Agora o jogo percebe na hora, salva tudo e <b>volta sozinho em 2 segundos</b>, já com o <b>🐢 Modo leve</b> ligado (dá para desligar no menu ❓).' },
    { id: 'n80', data: '21/11', t: '🔨 Refino até +15 e a Mina da Forja', d: 'O <b>Ferreiro Doran</b> agora refina até <b>+15</b>, mas precisa de muito material: arma, anéis e colar usam 🔶 <b>Minério Rúnico</b>; capacete, armadura, luvas e botas usam 🔷 <b>Pedra de Têmpera</b>. Os dois caem só na <b>⛏️ Mina da Forja</b> (fale com o Doran para descer): 3 ondas de monstros do seu nível e o <b>Capataz da Mina</b>, em 8 minutos, antes que ela desabe. <b style="color:#ff7060">Atenção: do +11 ao +15, se o refino falhar, a peça QUEBRA e some.</b> Para não quebrar, use o 🔰 <b>Selo da Forja Eterna</b>, que cai do Capataz. E agora dá para ver o Doran martelando na bigorna! <br><b>Também:</b> escolher uma missão no 📖 diário já faz o personagem andar até ela (e ela aparece no quadro da direita), e as setas ◀ ▶ encolhem o quadro de mensagens e o de missões.' },
    { id: 'n79', data: '21/11', t: '🕳️ Escada do Abismo, XP da Torre e caminhada', d: '<b>Preso na escada:</b> ao descer um andar do Abismo (ou subir na Torre), a pessoa chegava em cima da escadaria trancada e não conseguia sair (o bug do vídeo do Ludi). Agora chega no chão, ao lado dela. <b>XP da Torre e do Abismo</b> igual ao de um monstro comum do mesmo nível nos mapas, inclusive os Guardiões (ideia do Ludi: dava para ganhar 5 níveis sem esforço). <b>Andar até a missão</b> volta a parar quando você ataca ou usa uma habilidade, e também se a vida cair abaixo da metade.' },
    { id: 'n78', data: '20/11', t: '👾 Mais monstros e caminhada que não para', d: 'Os mapas mais vazios ganharam <b>mais monstros</b> (os mesmos de cada lugar): Solmira, Campos, Valdora, Floresta Morta e Vale dos Mortos. Quando o personagem <b>anda sozinho até a missão</b>, levar um golpe não faz mais ele parar: só para se a vida ficar abaixo de 30%. No <b>controle</b>, o <b>Y</b> agora faz o personagem andar sozinho até a missão seguida (aperte de novo para parar); o ataque continua no <b>A</b>.' },
    { id: 'n77', data: '20/11', t: '🐢 Modo leve (TV e aparelho que trava)', d: 'Na ajuda <b>❓</b> tem o novo <b>🐢 Modo leve</b>: tira as sombras e baixa a resolução para o jogo rodar liso. Bom para quem <b>espelha o celular na TV</b> (o iPhone gasta força mandando a imagem) ou tem aparelho que engasga. Toque de novo para voltar ao normal.' },
    { id: 'n76', data: '20/11', t: '🎮 Habilidades no controle e som mais firme', d: 'Na janela de <b>Habilidades</b>, o cursor do controle agora desce por todas elas (até as de 2ª e 3ª classe) e a lista rola junto; com uma janela aberta, o cursor não foge mais para os botões do jogo. O <b>som</b> volta sozinho no próximo toque quando o iPhone o corta (ex.: ao ligar o cabo da TV). Se jogar só com o controle e estiver mudo, <b>toque uma vez na tela</b>: o iPhone só libera o som depois de um toque.' },
    { id: 'n75', data: '20/11', t: '🎒 Mochila maior e som na TV', d: 'A <b>mochila</b> agora mostra muito mais itens de uma vez (antes eram só 2 fileiras). No <b>controle</b>, o cursor desce pela lista de itens e ela rola sozinha; no painel de <b>missões</b>, o <b>+N missões</b> abre o diário e você escolhe qual seguir. No <b>iPhone</b>, o som do jogo toca mesmo com a chave do <b>silencioso</b> ligada, e passa a sair na TV quando espelha a tela.' },
    { id: 'n74', data: '20/11', t: '🎮 Controle: agora dá para fazer tudo', d: 'Novo <b>modo cursor</b>: um quadrado amarelo anda pelos botões da tela com o analógico ou as setas, e o <b>A</b> aperta. Ele liga sozinho na tela de entrar, na escolha de personagem, nas conversas, lojas e janelas. Durante o jogo, aperte <b>☰</b> para usar os botões de cima, o painel de missões e o resto; <b>B</b> ou <b>☰</b> volta a jogar. E o <b>A</b> agora <b>fala com NPC, quadro e baú</b> quando você está perto (longe, ele ataca).' },
    { id: 'n73', data: '20/11', t: '🎮 Agora dá para jogar com controle', d: 'Controle de <b>Xbox</b>, PlayStation e outros, emparelhado por Bluetooth ou no cabo, no celular ou no PC. <b>Analógico esquerdo</b> anda, <b>direito</b> gira a câmera. <b>A</b> ataca (segure para continuar), <b>B</b> esquiva, <b>X</b> pula, <b>Y</b> fala com NPC. <b>LB, RB, LT, RT</b> e as <b>setas</b> usam os atalhos 1 a 8. <b>☰</b> abre a mochila e <b>⧉</b> o mapa. Nas conversas e lojas, as setas escolhem a opção e o <b>A</b> confirma. Se não reagir de primeira, aperte qualquer botão com o jogo aberto.' },
    { id: 'n72', data: '20/11', t: '🌳 Raízes de verdade na Floresta Morta', d: 'As raízes da Floresta Morta eram tubos iguais que pareciam bananas. Agora cada árvore tem <b>raízes diferentes</b>: de 3 a 8, curtas e compridas, grossas e finas, tortas, com nós, algumas <b>se dividem em duas</b> e todas afinam e entram na terra. Troncos e raízes ganharam <b>textura de casca</b> de verdade.' },
    { id: 'n71', data: '20/11', t: '🖤 Kravenox na Torre: andar e câmera consertados', d: 'O bug do vídeo do Ludi: no <b>Modo Fúria</b>, o Kravenox ficava sempre de frente, deslizando sem andar, mesmo subindo a escada de costas. Agora ele vira para o lado certo e anda normalmente, avermelhado pela fúria (parado, volta a aura de fogo). E ao chegar num <b>andar novo</b> da Torre ou do Abismo, a câmera não fica mais colada no personagem (aquele Kravenox gigante na tela).' },
    { id: 'n70', data: '20/11', t: '🃏 Cartas que não abriam na mochila', d: 'Algumas cartas dos mapas novos (Larva de Cristal, Caranguejo, Rei Caranguejo, Dama sem Olhos, Guarda de Ossos, Raiz Suspensa, Eco da Cidade, Sentinela Submersa, Sombra da Fonte e Guardião Branco) ficavam paradas na mochila: tocava e nada acontecia. <b>Consertado!</b> Agora elas abrem, mostram o nome, o bônus e onde encaixam.' },
    { id: 'n69', data: '20/11', t: '♻️ Resetar habilidades e atributos', d: 'Escolheu errado? Agora dá para <b>resetar</b>: o botão ♻️ fica na janela de <b>Habilidades</b> e na de <b>Atributos</b> e devolve todos os pontos. Cada jogador tem <b>3 resets grátis</b> de cada. Depois disso, só com o 📜 <b>Pergaminho do Esquecimento</b> (habilidades) ou a 🔄 <b>Pedra do Recomeço</b> (atributos), que o <b>Mercador</b> vende por <b>80.000 cr</b>. É caro de propósito!' },
    { id: 'n68', data: '20/11', t: '🖱️ Jogar no PC com mouse e teclado', d: 'No computador, como no Ragnarok: <b>clique no chão</b> para andar até lá, <b>clique no monstro</b> para ir até ele e atacar até cair, <b>clique no NPC</b> para conversar e <b>arraste</b> para girar a câmera (arrastar não ataca mais). Teclas: <b>WASD</b> anda · <b>J</b> ataca · <b>1 a 8</b> atalhos · <b>Espaço</b> pula · <b>Shift</b> esquiva · <b>F</b> fala · <b>Tab</b> mira o monstro mais perto · <b>I/B</b> mochila · <b>C</b> atributos · <b>K</b> habilidades · <b>Q</b> diário · <b>M</b> mapa · <b>L</b> bestiário · <b>G</b> grupo · <b>O</b> amigos · <b>P</b> mascotes · <b>Enter</b> chat · <b>U</b> música · <b>H</b> ajuda · <b>Esc</b> fecha tudo.' },
    { id: 'n67', data: '20/11', t: '📜 Árvores de habilidade bem maiores', d: 'Cada herói agora tem <b>22 habilidades</b> (antes 8): <b>14 novas</b>, sendo <b>6 passivas</b> (bônus que valem sempre: ataque, magia, HP, defesa, crítico, esquiva, roubo de vida, regeneração e força das curas) e <b>8 ativas</b>, espalhadas pela 1ª, 2ª e 3ª classe. Cada habilidade vai até o <b>nível 10</b> (antes 5). Você ganha 1 ponto por nível e <b>não dá para pegar tudo</b>: escolha o seu caminho. Abra no 📜.' },
    { id: 'n66', data: '20/11', t: '💛 Suporte no grupo', d: 'As <b>curas e proteções</b> agora valem para o <b>grupo todo que está perto</b> (até 15 m), não só para quem usou: Luz Dourada e Barreira de Luz do <b>Thornox</b>, Memória da <b>Lyra</b>, Quinta Marca e Escolha Livre da <b>Erya</b>, Abraço de Mãe da <b>Mãe</b> e as outras. Thornox e Lyra viram o suporte do grupo, e continuam com ataques fortes para jogar sozinho. (O Modo Fúria e os buffs com lado ruim continuam só para quem usou.)' },
    { id: 'n65', data: '20/11', t: '⚖️ Consertos do retorno do Ludi e do Rone', d: '<b>Torre e Abismo:</b> ao entrar num andar, as <b>duas escadas trancam</b> até limpar (não dá mais para fugir para o andar de trás). <b>XP das missões</b> com teto (principal até 25% de um nível; antes uma missão do Vale dava até 2 níveis). <b>Monstro bem mais fraco</b> que você cai com menos golpes (até 3x o dano). <b>Chefe preso</b> (como o Primeiro Guardião na ponte) agora salta até você. <b>Cartas</b> que apareciam com "❔" agora mostram o ícone. <b>Asas</b> compradas vão sozinhas para o atalho. <b>Kravenox e Verme</b>: itens mais fortes que qualquer peça dos amigos e 2 garantidos por vitória, com muito mais tesouro. <b>Desmontar</b> equipamento vira ⚙️ Pó de Forja, e o Ferreiro Doran faz peça nova com ele. <b>Cartas em 4 níveis:</b> Simples, Forte (15%), Invocada (4%) e Suprema (1%).' },
    { id: 'n64', data: '20/11', t: '📜 Minha Jornada', d: 'Menu ❓ → <b>📜 Minha Jornada</b>: tempo jogado, monstros derrotados, chefes, andar mais alto da Torre e do Abismo, vitórias contra Kravenox e Verme, missões, desafios, mascotes e os 5 monstros que você mais caçou.' },
    { id: 'n63', data: '17/11', t: '📖 Bestiário: quantos você já matou', d: 'O <b>📖 Bestiário</b> agora mostra <b>quantos de cada monstro você já matou</b> e o <b>nível de caça (★ de 1 a 10)</b>, com a barra até o próximo nível. Cada nível deixa a carta daquele monstro um pouco mais fácil de cair (+10%). No <b>nível 10</b> (2.000 abatidos nos comuns, 30 nos chefes), a <b>carta dele é sua</b>. E agora o bestiário mostra todos os 43 monstros (antes faltavam os dos mapas novos), e todos têm carta.' },
    { id: 'n62', data: '17/11', t: '📖 Livro de Mascotes', d: 'Para saber quais monstros dá para capturar: menu <b>❓ → 🐾 Livro de Mascotes</b> (ou na placa do quintal). Lista os 42 monstros com nível, o atributo que cada mascote dá, quais você já tem (✅) e quantas iscas tem (🪤). Tocando num, aparece onde ele vive, a chance da isca cair e o botão <b>🧭 Ir até onde ele vive</b>.' },
    { id: 'n61', data: '17/11', t: '📅 Presença do mês', d: 'Agora tem <b>prêmio de login</b>: cada dia em que você entra, recebe o prêmio do próximo dia do calendário (não precisa ser seguido). Os prêmios vão melhorando: poções, créditos, asas, Essências, Fragmentos Dourados e <b>Iscas surpresa</b> nos dias 7, 14, 21 e 28. O calendário vale só até o fim do mês; no dia 1 começa outro. Abre sozinho quando você entra, e fica também no menu ❓.' },
    { id: 'n60', data: '17/11', t: '🐾 Mascotes, ícones nas lojas e a Sorte', d: '<b>Mascotes</b> (ideia do Ludi, no jeito do Ragnarok): todo monstro do jogo pode virar mascote. Cada um deixa cair a sua <b>🪤 Isca</b> (rara). Use a isca (mochila → Usáveis) perto de um monstro daquele tipo: <b>quanto menos vida ele tiver, maior a chance</b>. Cada mascote dá um atributo; um anda com você e os outros ficam no <b>Quintal dos Mascotes</b>, no seu Sítio (é lá que você escolhe quem vai junto). E agora os NPCs de serviço têm um ícone na cabeça: 🧪 loja, ❤️ cura, ⚒️ ferreiro, 🧭 viagem. A <b>Sorte</b> ficou com a descrição certa: crítico, esquiva e um pouco de dano (ela nunca mudou os drops).' },
    { id: 'n59', data: '17/11', t: '🌙 Raízes Rastejantes: tronco de dia, monstro de noite', d: 'As <b>Raízes Rastejantes</b> dos Campos Dourados agora têm cor de madeira (antes eram quase pretas e sumiam no trigo) e são <b>15</b> em vez de 9. <b>De dia</b> ficam paradas, disfarçadas de tronco (💤 no nome). <b>À noite</b> acordam (🌙): andam, atacam quem passa perto e dão <b>50% a mais de XP</b>.' },
    { id: 'n58', data: '17/11', t: '🎤 Rádio do grupo e fim do leech', d: 'Em grupo aparece o botão <b>🎤</b> perto do pulo: <b>segure, fale e solte</b> (até 10 s). O recado chega só para o seu grupo, toca sozinho e fica no chat para ouvir de novo (▶). E a divisão do grupo agora é só entre <b>níveis parecidos</b>: até 10 níveis de diferença, parte inteira; de 10 a 20, vai caindo; mais de 20, nada (é o "leech").' },
    { id: 'n57', data: '17/11', t: '👥 Grupo divide o XP', d: 'Em <b>grupo</b>, o XP de cada monstro agora é <b>dividido igualmente</b> entre quem está perto, com <b>+10% de bônus por companheiro</b>: 2 no grupo = 55% para cada; 4 = 32,5% para cada. O monstro continua contando nas missões de todos.' },
    { id: 'n56', data: '17/11', t: '👥 Grupo divide os itens', d: 'Caçando em <b>grupo</b>, cada item que cai é <b>sorteado</b> entre quem está perto do monstro (até 45 m), inclusive quem matou. Aparece no chat para quem foi cada item. Os créditos (cr) continuam com quem deu o último golpe.' },
    { id: 'n55', data: '17/11', t: '🎒 Mostrar item no chat', d: 'No 💬 chat tem o botão <b>🎒</b>: escolha um item da mochila (ou equipado) e ele vai na mensagem com o nome colorido pela raridade. Quem receber toca no nome e vê a <b>ficha completa</b>: raridade, atributos, conjunto e de onde ele cai.' },
    { id: 'n54', data: '17/11', t: '🕳️ Abismo do Cisma: a Torre ao contrário', d: 'No fundo da <b>Cratera do Cisma</b> (entre Solmira e as Areias) abriu a boca do <b>Abismo</b>: 30 andares <b>descendo</b> para dentro da terra, monstros do <b>nível 60 ao 100</b>, um Guardião a cada 5 andares e pontos de retorno no 11º e no 21º. No Fundo fica o ninho do <b>Verme Colossal</b>: ele acorda <b>de 15 em 15 dias, no domingo às 20h</b> (o primeiro é dia 22/11) e fica 2 horas acordado. Ele sai de um dos 8 buracos, ataca e mergulha; corra até o círculo vermelho onde a terra treme. Prêmios novos: Lâmina de Dente Colossal, Anel do Ninho e Couraça de Quitina Abissal.' },
    { id: 'n53', data: '17/11', t: '💬 Chat novo: mundo, grupo e guilda', d: 'O <b>💬 chat</b> agora tem <b>histórico só das conversas</b> (sem os avisos do jogo no meio) e três canais no botão ao lado da caixa: <b>🌍 Mundo</b> (chega para todos, em qualquer lugar do mapa), <b>👥 Grupo</b> e <b>🛡️ Guilda</b>. Quando chega mensagem com o chat fechado, o botão 💬 fica marcado. E a tela <b>não dá mais zoom</b> ao digitar no iPhone.' },
    { id: 'n52', data: '17/11', t: '👥 Grupo (party) para caçar junto', d: 'Novo botão <b>👥 Grupo</b> no menu de cima: toque em <b>➕ Chamar</b> no nome de quem está on-line; a pessoa recebe o convite e entra no grupo (até 8). No grupo, quando um mata um monstro e o outro está perto (até 45 m), <b>os dois ganham XP</b> e o monstro <b>conta nas missões, desafios e aventuras dos amigos dos dois</b>. Os companheiros aparecem no quadro de Missões (com a vida) e em <b>verde</b> no minimapa.' },
    { id: 'n51', data: '16/11', t: '🎯 Saber quanto falta nas etapas', d: 'Ao tocar em <b>🎯 Caçar</b> numa etapa dos amigos ou dos desafios, o quadro de <b>Missões</b> passa a mostrar a etapa inteira com <b>quanto falta de cada monstro</b>, ao vivo. Quando um monstro chega no número pedido, aparece <b>✅ Pode parar de caçar esse!</b> e o que ainda falta. Tocar no quadro abre a etapa.' },
    { id: 'n50', data: '16/11', t: '🗼 Música nova na Torre do Cisma', d: 'A Torre ganhou uma trilha de <b>doom gótico</b>: lenta e pesada, com órgão de igreja, sinos, violoncelo, piano e guitarra arrastada. (A metal ópera de antes ficou guardada.)' },
    { id: 'n49', data: '16/11', t: '🎵 Uma música para cada lugar', d: 'Antes vários lugares repetiam a mesma música. Agora <b>cada um dos 23 lugares tem a sua</b>, todas da trilha do RPG do Kravenox: o mar na Praia de Cômodo, a de Valdora nas ruínas, a dos céus na Ponte dos Mortos, a submersa na Cidade Submersa, a das estrelas no Refúgio Suspenso e muito mais.' },
    { id: 'n48', data: '16/11', t: '✨ Irmandade Eterna: o guerreiro dourado', d: 'Quem veste as peças dos amigos agora <b>brilha</b>: com 4 a 7 peças, faíscas douradas; com as <b>8 peças, o personagem inteiro fica dourado</b>, envolto em luz, e todo mundo no mundo vê. E as peças dos amigos são só de quem fez a aventura: <b>não dá para trocar, pôr na banca nem vender</b>. O bônus máximo é só para quem completar as 8 aventuras.' },
    { id: 'n47', data: '16/11', t: '👑 Imperium: o conjunto está completo!', d: 'O <b>Imperium</b> chegou à <b>Cidadela do Cisma</b> com uma aventura pela Torre, pelas fronteiras do Reino e até o Kravenox acordado. No fim ele dá o <b>Anel Imperial</b>, a 8ª e última peça do <b>Conjunto da Irmandade Eterna</b>. Agora cada peça tem o seu amigo: junte as 8 para o bônus máximo. Tudo no botão 🤝.' },
    { id: 'n46', data: '16/11', t: '🧤 Ludivicki chegou e as janelas não se empilham mais', d: 'O <b>Ludivicki</b> está na <b>Vila de Solmira</b> com uma aventura que começa do zero (os primeiros bichinhos) e vai até o Kravenox. No fim ele dá as <b>Luvas Eternas</b>, a 7ª peça do Conjunto da Irmandade Eterna. E agora, ao abrir uma janela (mochila, guilda, loja, chat, atributos, bestiário, diário, mapa), <b>a outra fecha sozinha</b>. Nas etapas dos amigos tem também o botão <b>🎯 Caçar</b>.' },
    { id: 'n45', data: '16/11', t: '🤝 Três amigos novos', d: '<b>Michel Temmer</b> ⚔️ na Clareira de Lira (dá a <b>Espada Eterna</b>), <b>Will Sacer</b> ✝️, o sacerdote, na Vigília do Vale (dá o <b>Anel Sagrado</b>) e <b>Urakin Star</b> ⭐ no Refúgio Suspenso (dá as <b>Botas Estelares</b>). Cada um tem uma aventura de sete etapas, uma aura e um título só deles. Agora são 6 das 8 peças do Conjunto da Irmandade Eterna. Tudo no botão 🤝.' },
    { id: 'n44', data: '16/11', t: '🗡️ Amiga nova: Skye, a assassina', d: 'A <b>Skye</b>, assassina, chegou ao <b>Acampamento de Valdora</b>: sete etapas, das cinzas de Valdora até o Kravenox acordado. No fim ela dá o <b>Colar da Lâmina Oculta</b> (mítico, peça do Conjunto da Irmandade Eterna), a aura <b>Sombra Assassina</b> e o título « Amigo da Skye ». Acompanhe pelo botão 🤝.' },
    { id: 'n43', data: '16/11', t: '🤝 Botão dos Amigos e aviso de missão nova', d: 'Novo botão <b>🤝 Amigos</b> (ao lado do 📜): mostra as grandes aventuras dos amigos (<b>Nosferatur</b> e <b>Rivas</b>), em que etapa você está, o progresso de cada uma e o prêmio. Dá para <b>receber o prêmio de qualquer lugar</b> ou tocar em "Ir até" e o personagem vai sozinho. O número no botão avisa quando uma etapa está pronta. E o <b>📜</b> agora mostra <b>!</b> quando tem missão nova que você ainda não pegou (no diário ela aparece com 🆕).' },
    { id: 'n42', data: '16/11', t: '🎮 Mais jogos do Kravenox', d: 'Agora tem o botão <b>🎮 Mais jogos</b> (na tela inicial e no menu ❓): todos os jogos do universo Kravenox num lugar só (Quadros do Cisma, o RPG, a Plataforma e a Cratera do Cisma). E o botão <b>📤 Mandar</b> envia o link do Reino Quebrado Online para um amigo.' },
    { id: 'n41', data: '16/11', t: '🌍 Mapa do Mundo novo e drops de volta', d: 'O <b>Mapa do Mundo</b> agora mostra o desenho de verdade de cada lugar. Toque numa região e ela abre <b>ampliada</b>: toque no ponto onde quer ir e o personagem vai sozinho, passando por todas as passagens até chegar. E o <b>drop</b> voltou: quando o servidor "cochilava", ele esquecia os monstros e eles sumiam sem dar nada. Agora ele pede a lista de novo.' },
    { id: 'n40', data: '16/11', t: '🔧 Consertos: drops e caminho', d: 'Os monstros voltaram a dar <b>drop</b> (o servidor estava perdendo a lista de monstros e eles sumiam sem dar nada). E no <b>Mapa do Mundo</b>, ao tocar num lugar distante, o personagem agora vai passagem por passagem até chegar lá, sem voltar para a missão no meio do caminho.' },
    { id: 'n39', data: '16/11', t: '🌌 Mapa novo: Cidade Submersa (níveis 70 a 86)', d: 'No fim da Ponte dos Mortos agora tem um redemoinho: pule e caia na <b>Cidade Submersa</b> (livro I, caps. 9 e 10). Ilhas flutuando no vazio, pontes sobre o nada, cristais gigantes presos por raízes e um caminho <b>invisível</b> que só aparece sob os seus pés. Cidade nova: <b>Refúgio Suspenso</b>, com a Náufraga Ilene (história nova), quadro de caça e a Vidente Oren (desafios). No fundo espera <b>A Sombra da Fonte</b> (nível 86). Entrada a partir do nível 68.' },
    { id: 'n38', data: '16/11', t: '🌫️ Mapa novo: Vale dos Mortos (níveis 55 a 72)', d: 'A leste da Floresta Morta abriu o <b>Vale dos Mortos</b> (livro I, cap. 8): névoa até a cintura, milhares de túmulos, uma cicatriz escura no céu e, ao norte, a <b>Ponte dos Mortos</b>, feita de ossos sobre o abismo. Monstros: <b>Mão Pálida, Sussurro da Névoa, Dama sem Olhos, Sombra do Vale, Guarda de Ossos</b> e o chefe <b>O Primeiro Guardião</b> (Nv 72). Na <b>Vigília do Vale</b>: cura, loja, guia de viagem, quadro de caça, as missões da <b>Coveira Maren</b> (depois da Floresta) e os desafios do <b>Vigia Severo</b>. Novo <b>Conjunto do Vale dos Mortos</b> (lendário) e o <b>Cajado do Primeiro Guardião</b>.' },
    { id: 'n37', data: '16/11', t: '🔗 Conjunto da Irmandade Eterna', d: 'As peças míticas dos amigos (a <b>Armadura Noturna de Nosferatur</b> e o <b>Elmo das Mil Areias de Rivas</b>, e as próximas que vão chegar) formam o <b>Conjunto da Irmandade Eterna</b>, de <b>8 peças</b>. O bônus cresce: <b>2 peças</b> dão Dano +15, Defesa +15 e HP +250; <b>4 peças</b> dão Dano +40, Defesa +35, HP +600 e Crítico +5%; o <b>conjunto completo</b> dá Dano +120, Defesa +90, HP +1800, Crítico +15%, Velocidade +15% e SP +300.' },
    { id: 'n36', data: '16/11', t: '🐪 A Grande Jornada de Rivas', d: 'O <b>Rivas</b>, no Oásis de Kharum, agora tem uma jornada <b>gigante</b> de <b>7 etapas</b>: as areias, a caravana perdida, os senhores das dunas, as muralhas de Valdora, a Torre, o tesouro do deserto e, no fim, o <b>Kravenox acordado</b>. Prêmio final: o <b>Elmo das Mil Areias de Rivas</b> (Mítico, o melhor capacete do jogo), o rastro <b>Areias de Rivas</b> e o título <b>« Amigo de Rivas »</b>. O elmo e a armadura do Nosferatur fazem parte do <b>Conjunto da Irmandade Eterna</b>.' },
    { id: 'n35', data: '16/11', t: '📋 Quadro de Caça: 6 contratos por dia', d: 'Os <b>contratos de caça</b> dos quadros agora têm limite de <b>6 por dia</b>, somando todos os quadros (aceitos e entregues). O quadro mostra quantos você já usou hoje. À meia-noite libera de novo.' },
    { id: 'n34', data: '16/11', t: '💧 Habilidades gastam menos SP', d: 'O custo de SP das habilidades ficou mais justo: sobe <b>mais devagar</b> com o nível, e <b>nenhuma habilidade custa mais que 20% do seu SP máximo</b>. No nível 60, a mais cara caiu de cerca de 540 para cerca de 175.' },
    { id: 'n33', data: '16/11', t: '🏖️ Praia de Cômodo ganhou vida', d: 'Na <b>beira do mar</b> agora aparecem <b>Caranguejos Rubros, Medusas Errantes, Tartarugas Espinhosas e Serpentes das Ondas</b> (Nv 18–30) e o chefe <b>Rei Caranguejo</b> (Nv 34). A vila e o píer continuam tranquilos. <b>Coqueiros de verdade</b> balançando no vento, <b>golfinhos</b> saltando, um <b>veleiro</b> ao longe, peixinhos pulando, <b>bandeirinhas</b> na vila, guarda-sóis e pranchas na areia. Novo: <b>Água de Coco</b> (cura vida e SP). E a última etapa do <b>Nosferatur</b> agora pede <b>lutar com o Kravenox acordado</b> (1.500 de dano).' },
    { id: 'n32', data: '16/11', t: '🦇 A Grande Aventura do Nosferatur', d: 'O <b>Nosferatur</b>, na Praia de Cômodo, tem uma aventura <b>gigante</b> de <b>7 etapas</b>: caçar no Reino, pescar 300 peixes, derrotar Alfas e chefes, os três guardiões, chegar ao <b>topo da Torre</b> e vencer o Kravenox, juntar um tesouro e caçar 500 monstros da Floresta e de Valdora. Cada etapa dá coroas e itens. No fim: a <b>Armadura Noturna de Nosferatur</b> (Mítica, a melhor armadura do jogo), a <b>Aura Noturna de Nosferatur</b> e o título <b>« Amigo do Nosferatur »</b>.' },
    { id: 'n31', data: '16/11', t: '🎨 Nome só muda de cor no PvP', d: 'A <b>cor do nome</b> saiu da Loja de Visuais. Agora o nome só muda de cor como nas regras antigas: <b>rosa</b> em combate PvP e <b>vermelho com ☠ PK</b> para quem matou outro jogador. Quem tinha comprado uma cor <b>recebeu as coroas de volta</b>. Os desafios que davam cor agora dão: <b>Aura Quebra-Chefes</b>, <b>Rastro de Prata</b> e o título <b>« Memória Viva »</b>.' },
    { id: 'n30', data: '15/11', t: '🌍 Mapa do Mundo', d: 'Ao tocar no minimapa abre o <b>Mapa do Mundo</b>: todos os lugares (Praia de Cômodo, Reino Quebrado, Torre, Valdora e Floresta Morta), os <b>níveis</b> de cada um, as <b>passagens</b> que ligam um ao outro e um <b>VOCÊ ESTÁ AQUI</b> piscando. Toque no lugar onde você está para ver o mapa dele; toque em outro lugar e o personagem vai sozinho até a passagem certa.' },
    { id: 'n29', data: '15/11', t: '🧲 Itens vão direto para você', d: 'O que cai dos monstros que você derruba (coroas, materiais, poções, cartas, equipamentos) agora <b>voa sozinho até o seu corpo</b> e entra na mochila. Não precisa mais andar até cada item.' },
    { id: 'n28', data: '15/11', t: '🏖️ Lugar novo: Praia de Cômodo', d: 'Um lugar <b>tranquilo, sem monstros</b>: areia, mar, palmeiras, barcos, uma vila de pescadores e o <b>farol</b>. Entre pelo <b>arco no oeste do Reino</b>, perto da Vila de Solmira. No <b>píer</b> dá para <b>pescar</b> 🎣 (os peixes curam; tem Lagosta, Concha Rara e até a <b>Pérola de Cômodo</b>). Às vezes vem uma <b>Garrafa com Mensagem</b>. Quem pescar <b>100 peixes</b> ganha o título <b>« Filho de Cômodo »</b>.' },
    { id: 'n27', data: '15/11', t: '💧 SP agora acaba', d: 'As habilidades <b>custam mais SP conforme o seu nível</b> (no nível 60, 4 vezes o custo do começo). O SP volta <b>devagar em pé</b> e mais rápido <b>sentado</b> (🧘). A <b>Poção Azul</b> agora devolve 40 + 8% do seu SP máximo.' },
    { id: 'n26', data: '15/11', t: '🌲 Mapa novo: Floresta Morta (níveis 40 a 55)', d: 'A leste de Valdora abriu a passagem para a <b>Floresta Morta</b> (livro I, caps. 4 e 5): árvores colossais sem folhas, cristais nos troncos e raízes como ossos. Na <b>Clareira de Lira</b> há cura, loja, guia de viagem e quadro de caça. Monstros novos: <b>Larva Pernalta, Raiz Ossuda, Larva Cristalizada, Larva Antiga, Memória Aprisionada</b> e o chefe <b>Guardião Branco</b> (Nv 56). Ao norte, o <b>Templo da Primeira Raiz</b>. Missões novas com Lira (depois de terminar Valdora), o <b>Conjunto da Floresta Morta</b>, a <b>Lança da Ordem</b> e 3 desafios novos com o Andarilho Teodor.' },
    { id: 'n25', data: '15/11', t: '📊 Nível máximo 200 e atributos novos', d: 'O jogo agora vai até o <b>nível 200</b> (mapas novos vão chegar aos poucos). Para isso, cada nível pede <b>bem mais XP</b> e os atributos ficaram como no Ragnarok: <b>menos pontos por nível</b>, e cada ponto custa mais quanto mais alto o atributo (do 1 ao 10 custa 1, do 11 ao 20 custa 2…). <b>Todos os seus pontos foram devolvidos</b> para você redistribuir no 📊.' },
    { id: 'n24', data: '15/11', t: '🏆 Desafios: prêmios que só existem lá', d: 'Quatro mestres novos, um em cada cidade (<b>Caçadora Ivanna</b> na Vila, <b>Rivas</b> no Oásis, <b>Arauto Vex</b> na Cidadela e <b>Velha Brígida</b> no Acampamento), com <b>12 desafios</b>: matar <b>300 de cada</b> bicho, derrotar o <b>Kravenox 5 vezes</b>, o <b>Carrasco 5 vezes</b>, 50 Alfas, entregar centenas de materiais… Os prêmios <b>não se compram</b>: auras, rastros, a mascote <b>Larva Rainha</b>, títulos e <b>6 equipamentos lendários</b>. A estrela ★ dourada na cabeça do mestre avisa que um desafio está pronto. A contagem já inclui o que você caçou até hoje.' },
    { id: 'n23', data: '15/11', t: '🧺 27 materiais novos e frutas que curam', d: 'Como no Ragnarok, agora <b>cada monstro solta várias coisas</b>: um material comum, uma <b>fruta ou erva</b> (Maçã Silvestre, Mel Escuro, Folha Verde, Figo do Deserto e Erva Vermelha curam vida; <b>Erva Azul</b> devolve SP) e uma <b>raridade</b> de 1% a 2% (Núcleo Luminoso, Cristal Puro, Olho do Vazio, Aço de Valdora…). O <b>Ferreiro Doran</b> ganhou <b>11 receitas novas</b> com esses materiais, até a Espada de Valdora. E a música da Torre ficou mais suave, no estilo <b>metal ópera</b>.' },
    { id: 'n22', data: '15/11', t: '☠ Kravenox sem bots, Torre com metal gótico', d: 'Os 6 aventureiros de mentira que lutavam com o Kravenox <b>saíram</b>: o dano deles contava como se fosse seu, até de quem estava longe. Agora <b>só vale o dano dos jogadores de verdade</b> (a contagem recomeçou do zero). Os sons e avisos da luta só tocam para quem está no topo. A Torre ganhou <b>música nova de metal gótico</b> e as <b>portas no fim das escadarias</b> agora ficam de frente, com arco de pedra e tochas.' },
    { id: 'n21', data: '14/11', t: '🗼 Chefes da Torre não se curam mais sozinhos', d: 'Quando o Guardião do andar saltava para longe de onde nasceu, ele se curava e a vida voltava a encher a cada golpe. Corrigido: na Torre <b>nenhum monstro se cura sozinho</b>, e o chefe <b>não salta mais em cima das escadarias</b> (onde ficava preso fora do alcance).' },
    { id: 'n20', data: '14/11', t: '⌨️ Barra de atalhos com 8 espaços e câmera firme', d: 'A barra ficou <b>menor, com 8 espaços</b> (teclas 1 a 8). Para escolher o que vai em cada um, toque em <b>✏️</b>. Tocar num espaço vazio <b>não abre mais janela nenhuma</b> no meio da luta. E a câmera <b>não gira mais sozinha</b> nas escadarias da Torre: só você vira a câmera.' },
    { id: 'n19', data: '14/11', t: '🔥 Valdora refeita', d: 'As casas queimadas agora têm <b>paredes quebradas com janelas em arco</b>, cunhais de pedra e entulho. A muralha ganhou <b>ameias</b>, as torres têm cornijas, as carroças têm <b>rodas de raios</b>, as tendas do acampamento são de <b>pano caído</b> e a Passagem do Norte virou um <b>portal em arco ogival</b>. A estátua do pai segura uma espada de verdade.' },
    { id: 'n18', data: '14/11', t: '🌾 Sítio de Solmira refeito', d: 'Os canteiros agora são <b>leiras de terra com sulcos</b>, cercadas por troncos e estacas. A cerca do curral é de <b>postes roliços com ponta</b>, o bebedouro é um <b>tronco escavado</b> com água, e o espantalho ganhou camisa de pano, mangas com palha e chapéu de abas.' },
    { id: 'n17', data: '14/11', t: '🌴 Oásis de Kharum refeito (e o jogo mais leve)', d: 'As casas do Oásis viraram <b>casas de adobe arredondadas</b>, com cúpulas, toldos listrados e janelas de treliça. As barracas do mercado ganharam <b>panos caídos, cestos de frutas e jarros</b>. A fonte tem água correndo de verdade. E o jogo agora <b>não desenha o que está longe</b>: bem mais leve no celular.' },
    { id: 'n16', data: '14/11', t: '🏰 Torre do Cisma por fora: nova entrada', d: 'A Torre ganhou um <b>portal gótico</b> de pedra esculpida, com colunas, portas de madeira abertas, névoa na passagem e braseiros. A torre agora é uma peça só, que afina para o alto, com vitrais acesos e uma coroa de espinhos.' },
    { id: 'n15', data: '14/11', t: '🗼 Torre redesenhada (e bem mais leve)', d: 'Os andares agora são <b>salões grandes</b>, com <b>escadarias laterais</b> que dão a volta pela parede: uma <b>sobe</b> até a porta do andar de cima (selada até você limpar o andar) e outra <b>desce</b> por um vão no chão. <b>Mais monstros por andar</b> (10 a 18). Ao chegar num andar você tem <b>3 segundos de proteção</b>. A Torre ficou muito mais leve para o celular.' },
    { id: 'n13', data: '13/11', t: '🎁 Vantagens de estar numa guilda', d: 'A guilda tem <b>nível de 1 a 10</b>: 10% do XP de monstro dos membros vai para ela (sem tirar nada de ninguém). Cada nível dá <b>+1% de XP e de coroas</b>; no nível 2, <b>5% de desconto</b> nas lojas; no 3, <b>+5% de vida</b>; no 5, <b>+5% de dano</b>; no 7, <b>+10% de itens</b>. <b>Aura de grupo:</b> cada membro perto dá +10% de XP (até +30%). <b>Chamado:</b> viaje até um membro online por 500 cr.' },
    { id: 'n12', data: '13/11', t: '🛡️ Guildas e PvP livre na Torre', d: 'Toque em <b>🛡️ Guilda</b> (no menu de cima) para <b>criar</b> uma guilda (10.000 cr), <b>convidar</b>, organizar <b>líder, oficiais e membros</b>, escrever o <b>aviso</b> e conversar no <b>chat da guilda</b>. A sigla aparece em cima do nome. <b>A Torre do Cisma virou zona de guerra:</b> lá dentro qualquer jogador pode atacar você, menos quem é da sua guilda, e matar não deixa o nome vermelho.' },
    { id: 'n14', data: '14/11', t: '☠ Kravenox acorda neste sábado às 20h', d: 'Ele fica acordado <b>6 horas</b>: de <b>sábado às 20h até as 2h de domingo</b> (horário de Brasília), no topo da Torre do Cisma. A vida dele é dividida entre todos que batem. <b>Só ganha o prêmio quem lutou</b> (pelo menos 1.500 de dano). Quando ele cai, some para todo mundo e só volta no <b>sábado seguinte</b>.' },
    { id: 'n10', data: '13/11', t: '🗼 Torre: vida do chefe, sacola no andar e câmera', d: 'Os chefes agora mostram a <b>barra de vida no topo da tela</b>. Quem morre na Torre deixa a <b>sacola no andar onde caiu</b>, e a entrada tem o botão <b>🎒 Voltar até a sua sacola</b>. A câmera não fica mais presa na parede nas escadarias, e as luzes das tochas ficaram suaves.' },
    { id: 'n9', data: '13/11', t: '🏘️ Casas novas na Cidadela do Cisma', d: 'As casas da Cidadela foram refeitas: térreo de pedra, andar de cima com vigas de madeira, telhado de duas águas e janelas acesas.' },
    { id: 'n8', data: '13/11', t: '⌨️ Barra de atalhos do seu jeito', d: 'A barra voltou a ser uma linha só, com a <b>barra 2 do lado</b> (6 + 6 espaços). Toque em <b>✏️</b> (no fim da barra) e depois num espaço para escolher a habilidade ou o item que fica nele. Também dá para usar o 📌 na árvore de habilidades e na mochila.' },
    { id: 'n7', data: '13/11', t: '📶 Aviso de internet e modo Economia de dados', d: 'O jogo mostra quanto de internet está gastando e tem o modo <b>Economia de dados</b>, que gasta mais ou menos a metade. Músicas, texturas e modelos ficam guardados no aparelho e não são baixados de novo a cada versão.' },
    { id: 'n6', data: '13/11', t: '🌐 O jogo agora é todo on-line', d: 'Entre com <b>usuário e senha</b>. Seus personagens ficam guardados no servidor: entra de qualquer aparelho e nada se perde se o celular quebrar. Sem internet, o jogo pausa até a conexão voltar.' },
    { id: 'n5', data: '13/11', t: '👾 Monstros compartilhados', d: 'Todos veem e batem nos <b>mesmos monstros</b>. O XP é dividido pela parte do dano de cada um; itens e coroas ficam com quem dá o último golpe.' },
    { id: 'n4', data: '13/11', t: '🗺️ Valdora: mapa novo ao norte', d: 'Pela <b>Passagem do Norte</b>, no alto das Areias Rubras. Monstros do nível 24 ao 36 e missões a partir do nível 24 com o Vigia Morvan.' },
    { id: 'n3', data: '13/11', t: '🗼 Torre do Cisma com 30 andares', d: 'Escadarias de verdade, um Guardião a cada 5 andares e Kravenox nível 60 no topo, com item Mítico garantido.' },
  ];
  const get = k => { try { return localStorage.getItem(k); } catch (e) { return null; } };
  const set = (k, v) => { try { localStorage.setItem(k, v); } catch (e) { } };
  const vistos = () => (get('reino-avisos-vistos') || '').split(',');
  const novas = () => NOVIDADES.filter(n => !vistos().includes(n.id));
  const mb = b => (b / 1048576).toFixed(b < 10485760 ? 1 : 0).replace('.', ',');

  function usoTxt() {
    const u = typeof Net !== 'undefined' ? Net.uso : null;
    if (!u || !(u.in + u.out)) return '';
    const tot = u.in + u.out, min = Math.max(1, (Date.now() - u.t0) / 60000);
    return `<div class="av-uso">Nesta sessão: <b>${mb(tot)} MB</b> em ${Math.round(min)} min (≈ <b>${mb(tot / min * 60)} MB por hora</b> no seu ritmo de agora)</div>`;
  }
  function html(lista) {
    const eco = typeof Net !== 'undefined' && Net.economia();
    return `<div class="av-box"><div class="av-t">📢 Avisos e novidades<button class="av-x" aria-label="Fechar">✕</button></div><div class="av-corpo">
      <div class="av-item av-dados"><b>📶 Este jogo usa internet o tempo todo</b>
        <p>O Reino Quebrado é todo on-line. <b>No 4G/5G ele gasta dados do seu plano (crédito)</b>; no Wi-Fi, não.</p>
        <ul><li>Primeira vez: baixa uns <b>15 MB</b> (o jogo e as músicas). Depois fica guardado no aparelho e só baixa o que mudar.</li>
        <li>Jogando sozinho: cerca de <b>10 a 15 MB por hora</b>.</li>
        <li>Com amigos e monstros por perto: cerca de <b>30 a 70 MB por hora</b>.</li>
        <li>Modo <b>Economia de dados</b>: mais ou menos <b>a metade</b> (os outros jogadores e monstros andam um pouco menos suave).</li></ul>
        ${usoTxt()}
        <p class="av-dica">Dica: jogue no Wi-Fi quando puder.</p></div>
      ${lista.map(n => `<div class="av-item"><b>${n.t}</b> <small>${n.data}</small><p>${n.d}</p></div>`).join('')}
      </div><div class="av-bt"><button class="av-eco">${eco ? '📉 Economia de dados: LIGADA' : '📶 Economia de dados: desligada'}</button><button class="av-ok">Entendi</button></div></div>`;
  }
  // mostra o painel; feito() roda quando a pessoa toca em "Entendi"
  function mostrar(todas, feito) {
    const lista = todas ? NOVIDADES : novas();
    let el = document.getElementById('avisos'); if (el) el.remove();
    el = document.createElement('div'); el.id = 'avisos'; el.innerHTML = html(lista); document.body.appendChild(el);
    const ligar = () => {
      el.querySelector('.av-eco').onclick = () => { const on = !(typeof Net !== 'undefined' && Net.economia()); set('reino-economia', on ? '1' : '0'); if (typeof Audio8 !== 'undefined') Audio8.sfx('click'); el.innerHTML = html(lista); ligar(); };
      el.querySelector('.av-x').onclick = () => el.querySelector('.av-ok').click();
      el.querySelector('.av-ok').onclick = () => { if (typeof Audio8 !== 'undefined') Audio8.sfx('click'); set('reino-avisos-vistos', NOVIDADES.map(n => n.id).join(',')); el.remove(); if (feito) feito(); };
    };
    ligar();
  }
  // depois do login: só aparece se tiver novidade que a pessoa ainda não viu
  function seTiverNovo(feito) { if (novas().length) mostrar(false, feito); else feito(); }
  return { mostrar, seTiverNovo };
})();
